INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(232, 'koKR', 'Sprawunek dla aptekarki Zinge', 'Królewskie Zakłady Chemiczne potrzebują twojej pomocy. Słuchaj uważnie, a oboje możemy skorzystać na moim planie.$B$BAptekarz Keever z sąsiedniej sali może i jest... niespełna rozumu... ale jego badania mogłyby wydać owoce, gdyby prowadził je ktoś bystry. Na szczęście ja jestem kimś takim. Zanieś to zamówienie Alessandrowi Luce, właścicielowi Rozmaitości „Błękitny Księżyc”. Da ci zestaw do testów. Kiedy go dostaniesz, przynieś go do mnie, a szczegółowo objaśnię ci zadanie.', 'Zanieś zamówienie Alessandrowi Luce w Podmieście.', '', '', '', '', '', '', 0),
(238, 'koKR', 'Sprawunek dla aptekarki Zinge', 'Zestaw jest gotowy, $n. Aptekarka Zinge bez wątpienia będzie go chciała mieć jak najszybciej. Zanieś go jej bez zwłoki i przekaż, że dopiszę koszt zestawu do rachunku Zakładów. I proszę, przekaż jej moje najserdeczniejsze pozdrowienia.$B$BNo, nie stój tak. Taki już los zwykłego posłańca, prawda?', 'Zanieś zestaw do testów terenowych aptekarce Zinge w Podmieście.', '', '', '', '', '', '', 0),
(243, 'koKR', 'W teren', 'Udasz się na pustynię Tanaris, by zbadać konsystencję tkanek żyjących tam bazyliszków, skorpidów i hien. Zdobądź próbki tkanek i sprawdź je zestawem, który masz przy sobie. Licz się z tym, że sporo próbek odpadnie. Potrzebuję ośmiu przydatnych próbek każdego rodzaju stworzeń.$B$BPoza tym gobliny z Gadżetonu mają źródło zasilania, którego trzeba użyć w tak przerobionym zestawie. Porozmawiaj z głównym inżynierem Zęzoświstem i zdobądź od niego jedno.$B$BWróć do mnie dopiero, gdy ci się uda.', 'Porozmawiaj z głównym inżynierem Zęzoświstem w Gadżetonie o źródle zasilania do zestawu testowego.', '', '', '', '', '', '', 0),
(357, 'koKR', 'Tożsamość lisza', 'Na wyspie na Jeziorze Jasnym, na północy, mieszka pewien lisz. Choć jest Porzuconym o wolnej woli, uważa wszystkich innych nieumarłych za niewolników Plagi i posyła swoje sługi na każdego, kto się do niego zbliży.$B$BSkoro jednak jest Porzuconym, królowa zechce go mieć. A jeśli zna się na nekromancji, jego wiedza byłaby dla nas... wielce użyteczna.$B$BBy poznać jego tożsamość i talenty, muszę zobaczyć jego księgę zaklęć. Zakradnij się do jego obozu, zdobądź ją i wróć do mnie.', 'Przynieś Księgę zaklęć lisza Bethorowi Lodowemu Odłamkowi w Podmieście.', '', 'Wróć do Bethora Lodowego Odłamka na Polanach Tirisfal.', '', '', '', '', 0),
(444, 'koKR', 'Pochodzenie Zgniłofutrych', 'Odparowałem posokę, którą $gprzyniosłeś:przyniosłaś;, i rozdzieliłem ją na składniki podstawowe. Moje ustalenia nie są rozstrzygające, ale stwierdziłem, że przy jej tworzeniu użyto magii czarnoksięskiej i nekromanckiej.$B$BGdy ja będę dalej badał posokę, ty zanieś próbkę Bethorowi Lodowemu Odłamkowi w Podmieście. Bethor nie jest aptekarzem, ale jego znajomość magii może pomóc rozwikłać zagadkę Zgniłofutrych.$B$BIdź. Znajdziesz Bethora w Dzielnicy Magów w Podmieście.', 'Zanieś Próbkę posoki Bethorowi Lodowemu Odłamkowi w Podmieście.', '', '', '', '', '', '', 0),
(446, 'koKR', 'Thule Kruczy Szpon', 'Tę posokę sporządził mój dawny kolega, Thule Kruczy Szpon. Przed wielką wojną był młodym, obiecującym magiem, ale gdy Król Lisz doszedł do władzy, zdradził swoich braci i sprzymierzył się z Plagą.$B$BNie wiedziałem, że wciąż żyje, ani że to on prowadzi Zgniłofutrych w ich wypadach przeciwko nam!$B$BZnam wiele jego zaklęć i mogę pomóc przyrządzić miksturę, która je zneutralizuje. Zanieś ten zwój aptekarzowi Renferrelowi. Są w nim inkantacje potrzebne do mikstury.', 'Zanieś Zwój Bethora aptekarzowi Renferrelowi w Grobowisku w Srebrzystym Borze.', '', '', '', '', '', '', 0),
(447, 'koKR', 'Receptura śmierci', 'Armie Arthasa są przytłaczające. Ale nową zarazą moglibyśmy raz na zawsze wytępić zarówno armię Plagi, jak i ludzkie robactwo.$b$bMoje badania dowiodły, że pajęcza krew połączona z toksyną z serca siwego niedźwiedzia daje zabójczy eliksir. Zbierz próbki od pająków w Obślizgłej Czerni na północnym zachodzie i od niedźwiedzi przemierzających Srebrzysty Bór. Dostarcz składniki mistrzowi aptekarzowi Faranellowi z Królewskich Zakładów Chemicznych w Podmieście.', 'Zbierz 6 serc siwego niedźwiedzia i 6 próbek pajęczej krwi i dostarcz je mistrzowi aptekarzowi Faranellowi w Podmieście.', '', 'Wróć do mistrza aptekarza Faranella w Aptekarium w Podmieście.', '', '', '', '', 0),
(450, 'koKR', 'Receptura śmierci', 'Możesz jeszcze przysłużyć się Królewskim Zakładom Chemicznym, $N.$b$bGdy Arugal rzucił na las swoją nędzną magię, przeklął jednego z naszych najbardziej obiecujących członków, aptekarza Berarda. Teraz Berard jest bezmyślnym sługą Arugala i nie mamy z niego żadnego pożytku. Ale jego odkrycia mogą mieć wartość. Badał starożytną zarazę, która przed wiekami wybiła całe życie w Jeziorze Lordamere.$b$bOdzyskaj Dziennik Berarda z jego pracowni w karczmie w Wiosce Stosowego Lasu i zanieś go aptekarzowi Renferrelowi.', 'Odzyskaj dziennik aptekarza Berarda z Wioski Stosowego Lasu i zanieś go aptekarzowi Renferrelowi w Grobowisku.', '', 'Wróć do aptekarza Renferrela w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(451, 'koKR', 'Receptura śmierci', 'Według Dziennika Berarda mech z jeziornych czatowników i pełzaczy może się przydać w naszym dążeniu do uwarzenia nowej zarazy. Te bestie żyją na wyspach Jeziora Lordamere na wschodzie.$b$bBerard wspomina też o bardzo rzadkim stwardniałym guzie, który znalazł u murloka z Plugawopłetwych. Guz jest ponoć tak rzadki, że Berardowi udało się zdobyć tylko jeden.$b$bZbierz próbki mchu oraz ten rzadki stwardniały guz i zanieś je mistrzowi aptekarzowi Faranellowi w Podmieście.', 'Przynieś 6 próbek mchu jeziornego pełzacza, 6 próbek mchu jeziornego czatownika i stwardniały guz mistrzowi aptekarzowi Faranellowi w Podmieście.', '', 'Wróć do mistrza aptekarza Faranella w Aptekarium w Podmieście.', '', '', '', '', 0),
(491, 'koKR', 'Różdżka dla Bethora', 'Thule powiedział mi kiedyś, że dawno temu wraz z dwoma kolegami stworzył magiczną różdżkę, splecioną z różdżek, które każdy z magów miał jako uczeń. Ta różdżka była symbolem ich przyjaźni i choć Thule ją znienawidził, nie potrafił się z nią rozstać ani pozwolić, by mieli ją pozostali. Ukradł więc różdżkę i ukrył ją w Twierdzy Fenris.$B$BMasz. Zanieś różdżkę Bethorowi Lodowemu Odłamkowi, jednemu z dawnych przyjaciół Thule\'a. Na pewno zechce ją mieć.', 'Zanieś Plecioną różdżkę Bethorowi Lodowemu Odłamkowi w Dzielnicy Magów w Podmieście.', '', '', '', '', '', '', 0),
(495, 'koKR', 'Korona woli', 'Mug\'Thol i jego ogrza banda zostali wysłani do Alterak, by zdobyć Koronę woli dla lady Sylwany. Niestety, zamiast ją dostarczyć, ten idiota postanowił ją przymierzyć... Najwyraźniej ogry nie potrafią się oprzeć niczemu, co jasne i błyszczące.$b$bJego nieporadne wybryki stały się jednak pewnym problemem. Korona woli pozwoliła mu oprzeć się opętaniu, które na niego rzucono, by służył lady Sylwanie.$b$bMroczna Pani chce, żeby posłużył za przykład. Udaj się do Smolnego Młyna w Międzygórzu i zamelduj się u Melisary, mojej zastępczyni.', 'Zamelduj się u Melisary w Smolnym Młynie w Międzygórzu.', '', '', '', '', '', '', 0),
(513, 'koKR', 'Eliksir agonii', 'Już myślałem, że minie kolejny dzień bez odrobiny radości, a ty $gprzyniosłeś:przyniosłaś; mi te cudowne kwiaty błotopyska.$b$bNajpierw utrę je na porządny kompozyt. Potem mistrz aptekarz Faranell w Podmieście musi dodać do niego swój koloid rozkładu i wtedy będziemy gotowi na naprawdę przednią zabawę!$b$bMasz, weź ten Kompozyt z błotopyska i natychmiast zanieś go mistrzowi Faranellowi, $N.', 'Zanieś Kompozyt z błotopyska mistrzowi aptekarzowi Faranellowi w Podmieście.', '', '', '', '', '', '', 0),
(521, 'koKR', 'Korona woli', 'Zostało już tylko dostarczyć Koronę woli Sharlindrze w Podmieście. Ona dopilnuje, by trafiła do lady Sylwany. Ostrzegam cię, $n, nie myśl nawet, by użyć jej do własnych celów. Los Mug\'Thola powinien być wystarczającą przestrogą.', 'Dostarcz Koronę woli Sharlindrze w Podmieście.', '', '', '', '', '', '', 0),
(530, 'koKR', 'Zemsta męża', 'Valdred, niegdyś mój dobry przyjaciel, zamordował moją żonę. Choć nie jestem zdolny do żałoby, pragnę zemsty. Jeśli zabijesz Valdreda i przyniesiesz mi jego przeklęte dłonie, nagrodzę cię.$B$BOstatnio słyszałem, że był przy Murze Szarogrzywych na południu Srebrzystego Boru i próbował uciec do królestwa Gilneas.', 'Zabij Valdreda Moraya.$B$BPrzynieś jego dłonie Raleighowi Andreanowi w Podmieście.', '', 'Wróć do Raleigha Andreana w Ruinach Lordaeronu na Polanach Tirisfal.', '', '', '', '', 0),
(550, 'koKR', 'Bitwa o Międzygórze', 'Ponieważ w Bitwie o Międzygórze $gwalczyłeś:walczyłaś; z takim męstwem i wytrwałością, napisałam tę pochwałę, sławiącą twoje bohaterskie czyny w walce, by naczelne dowództwo mogło je docenić.$b$bZanieś tę zapieczętowaną pochwałę Bragorowi Krwawej Pięści w Podmieście. Idź z dumą, $N.', 'Zanieś Zapieczętowaną pochwałę Darthalii Bragorowi Krwawej Pięści w Podmieście.', '', '', '', '', '', '', 0),
(728, 'koKR', 'Do Podmiasta po Kompendium Yagyina', 'Tablica mówi wiele. Ale nie dość! O wiele za mało!$B$BIstnieje księga, kompendium, które Yagyin spisał w dawnych wiekach. Ci... od których uciekłem... trzymają tę księgę w wielu miejscach. A ich najuczeńsi ją studiują. Kryje ogromną wiedzę. Wiedzę, która nas ochroni!$B$BIdź do Opiekuna Bel\'dugura w Podmieście Lordaeronu. Pokaż mu ten symbol, a weźmie cię za jednego z nich. Poproś go o Kompendium Yagyina... i przynieś je mnie!', 'Zanieś Symbol Młota Opiekunowi Bel\'dugurowi w Podmieście.', '', '', '', '', '', '', 0),
(864, 'koKR', 'Powrót do aptekarki Zinge', '„Proszę bardzo, źródło zasilania bezpiecznie wyjęte, dane zachowane. No to szerokiej drogi i tak dalej. Mam nadzieję, że ten niecny eksperyment naukowy ci się udał i w ogóle”.$B$BGoblin odwraca się od ciebie, by zająć się żądaniami Wodociągów Gadżetonu. Zabezpieczasz zapieczętowany zestaw na drogę powrotną do Podmiasta. Czeka tam na ciebie i na zestaw aptekarka Zinge.', 'Zanieś Zapieczętowany zestaw do testów terenowych aptekarce Zinge w Podmieście.', '', '', '', '', '', '', 0),
(1013, 'koKR', 'Księga Ura', '$N, w Twierdzy Cienistego Kła jest księga, Księga Ura, którą bardzo chciałbym mieć w swojej kolekcji. Ur był wielkim magiem Dalaranu przed nadejściem Plagi, a jego badania nad innymi światami mają wielką wartość dla... pewnych stronnictw wśród Porzuconych.$B$BWejdź do Twierdzy Cienistego Kła i znajdź tę księgę. Przynieś mi ją, a zdam naszej Mrocznej Pani raport z twojej służby...', 'Przynieś Księgę Ura Opiekunowi Bel\'dugurowi w Aptekarium w Podmieście.', '', 'Wróć do Opiekuna Bel\'dugura w Aptekarium w Podmieście.', '', '', '', '', 0),
(1109, 'koKR', 'Guano raz, guano dwa, sprzedane!', 'Jak widzisz, $n, w Królewskich Zakładach Chemicznych prowadzimy bardzo... interesujące eksperymenty.$b$bJako tutejszy mistrz nadzoruję nasze najambitniejsze próby alchemiczne. Tyle pracy, a tak mało czasu!$b$bWyglądasz na kogoś, kto sporo się najeździł po świecie. Może zdołasz mi pomóc.$b$bPotrzebuję rzadkiej substancji. Obrzydliwy materiał: pochodzi od rzadkiego gatunku nietoperzy, spotykanego tylko w tej cuchnącej dziurze zwanej Ciernisko Brzytwoskórych. Przynieś mi guano nietoperzy z Cierniska, abyśmy mogli zacząć pracę...', 'Przynieś 1 kupkę guana z Cierniska mistrzowi aptekarzowi Faranellowi w Podmieście.', '', 'Wróć do mistrza aptekarza Faranella w Aptekarium w Podmieście.', '', '', '', '', 0),
(1113, 'koKR', 'Serca żarliwości', 'Pewnie zapytasz, po co mi rzadki rodzaj guana. Otóż w tym eksperymencie chcę zobaczyć, jak na siebie działają dwie diametralnie przeciwne substancje chemiczne, zwłaszcza gdy obie połączy się z nader toksycznym czynnikiem, by uzyskać jak najbardziej... upiorne rezultaty.$b$bW północno-wschodnich szczytach Polan Tirisfal leży Szkarłatny Klasztor. Tam gromadzą się oszalali wyznawcy Szkarłatnej Krucjaty, zarówno w murach, jak i poza nimi. Nieważne, których zabijesz – każdy z nich może mieć serce, którego potrzebuję.', 'Mistrz aptekarz Faranell w Podmieście chce 20 Serc żarliwości.', '', 'Wróć do mistrza aptekarza Faranella w Aptekarium w Podmieście.', '', '', '', '', 0),
(1159, 'koKR', 'Próba wiedzy', 'Dobra robota, $N. $GPrzeszedłeś:Przeszłaś; pierwszą część Próby wiedzy, ale wciąż pozostaje pytanie, na które musisz odpowiedzieć. Tyle że nie mnie je zadawać.$B$BOdszukaj Parquala Fintallasa w stolicy Lordaeronu. Był wielkim historykiem ludzi, zanim dopadła go Zaraza. Teraz nadal szuka oświecenia, choć innej natury.$B$BZanim cię o cokolwiek zapyta, postawi ci jeszcze jeden warunek, ale jak dotąd radzisz sobie po mistrzowsku – na pewno pokonasz i tę przeszkodę.', 'Odnajdź Parquala Fintallasa w Podmieście.', '', '', '', '', '', '', 0),
(1160, 'koKR', 'Próba wiedzy', 'Powiem ci, czego masz szukać, a nawet zadam ci swoje pytanie, ale nie dlatego, że chcesz się wykazać. Wiedza jest o wiele ważniejsza niż siła. Nawet gdy inni zdają się prześcigać cię w umiejętnościach, twoja wiedza o świecie okaże się cenniejsza.$B$BIdź do Klasztoru na północy Polan Tirisfal. W tamtejszej bibliotece znajduje się księga zatytułowana „Początki zagrożenia ze strony nieumarłych”. Zepsuci dziś paladyni szkolili się z niej do walki z takimi jak ja.$B$BPrzynieś mi ją.', 'Znajdź „Początki zagrożenia ze strony nieumarłych” i zanieś je Parqualowi Fintallasowi w Podmieście.', '', 'Wróć do Parquala Fintallasa w Podmieście.', '', '', '', '', 0),
(1164, 'koKR', 'Okraść złodziei', 'Ladacznica! Świnia! Kenata wciąż żyje, jej rodzina jest zdrowa i ma się świetnie, a ja cierpię. Porzucona, w rzeczy samej!$B$BMoja rodzina odeszła, zabrała ją zaraza. Nasz majątek także przepadł – splądrowany i spalony w czasie wojny. A po tym wszystkim ona i jej parszywe dzieciaki miały czelność ukraść jedyne cenne rzeczy, jakie mi zostały.$B$BNie dbam już o to, co ukradli. Teraz chcę ich głów!$B$BZabij ich dla mnie! Idź do Gospodarstwa Dabyrie\'ów na Wyżynach Aratorskich, na północny wschód od Punktu Schronienia.', 'Przynieś głowy Kenaty, Fardela i Marcela Dabyrie Genavie Callow w Podmieście.', '', 'Wróć do Genavie Callow nad Jeziorem Lordamere w Górach Alterak.', '', '', '', '', 0),
(1359, 'koKR', 'Przesyłka dla Zinge', 'Wilcze serca, które $gzdobyłeś:zdobyłaś;, mają właściwość niespotykaną w podobnych okazach. Jest w nich toksyczność, która powinna zabijać te same wilki, w których te serca biją!$B$BTo zdumiewające i musimy to dalej badać. Zatrzymałem kilka próbek serc. Zanieś je mojej koleżance, aptekarce Zinge. Znajdziesz ją w naszej siedzibie w Podmieście.', 'Zanieś Próbki wilczych serc aptekarce Zinge w Podmieście.', '', '', '', '', '', '', 0),
(1394, 'koKR', 'Ostatni etap', 'Dobrze się $gspisałeś:spisałaś;, $N. $GPrzeszedłeś:Przeszłaś; moją próbę i te przed nią. Wróć do Dorna w Tysiącu Filarów. Wyczuje w tobie przemianę i zobaczy, że twój umysł, ciało i duch są dość silne, by należała ci się nagroda za twoje starania.$B$BPozostań $gwierny:wierna; równowadze, którą $gokazałeś:okazałaś; w tych próbach, $N. Jeśli tak będzie, Dorn w przyszłości znów cię wypróbuje.', 'Porozmawiaj z Dornem Tropicielem Równin w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1476, 'koKR', 'Serca czystych', 'Ludzie honoru i dobroci? Czy tacy w ogóle istnieją?$b$bKosztowało mnie to wiele poszukiwań, ale ze strzępów zasłyszanych opowieści zdołałem wyłowić dwóch, którzy powinni się nadać.$b$bPierwszy to Dalin Kuźnomistrz, który poświęcił się opiece nad uchodźcami z Lordaeronu, odrzuconymi przez własnych pobratymców przy Murze Szarogrzywych.$b$bDrugi to Comar Villard, człowiek, który pozostaje wierny swojej utraconej miłości i przemierza Bagniska w poszukiwaniu znaku od żony.$b$bDostarcz ich serca Carendinowi. Ale najpierw pozwól, że pokażę ci twoją zwierzynę.', 'Przynieś serca Dalina Kuźnomistrza i Comara Villarda Carendinowi Halgarowi w Świątyni Potępionych.', '', 'Wróć do Carendina Halgara na Polanach Tirisfal.', '', '', '', '', 0),
(1657, 'koKR', 'Zasmrodzić Południowy Brzeg', 'Świętuj Zaduszniki z klasą... przysparzając zmartwień naszym wrogom w Południowym Brzegu!$B$BWeź jedną z tych specjalnie przygotowanych cuchnących bomb. Wypełnia ją smród, którego nie zniesie żaden człowiek – ani zresztą żadna bestia o słabej woli. Żeby zadziałała, musisz ją rzucić w samo serce Południowego Brzegu, więc przygotuj się na walkę z Przymierzem!$B$BGdy wykonasz to zadanie... ten hołd dla naszego wyzwolenia, wróć do mnie!', 'Rzuć trzy cuchnące bomby Porzuconych w samo serce Południowego Brzegu w Międzygórzu i wróć do przywoływaczki mroku Yanki na festiwalu Wiklinowego Człowieka na Polanach Tirisfal.', '', 'Wróć do przywoływaczki mroku Yanki w Ruinach Lordaeronu na Polanach Tirisfal.', 'Rzuć cuchnącą bombę w Południowy Brzeg', '', '', '', 0),
(1841, 'koKR', 'Velora Nitely i brutalne nagolenniki', 'Mówi się, że przed śmiercią Velora Nitely była jedną z najlepszych płatnerek w Lordaeronie. Śmierć, jak się zdaje, nie umniejszyła jej talentu. Porozmawiaj z Velorą – wykuje ci brutalne nagolenniki.$B$BVelora zajmuje się swoim rzemiosłem w Podmieście Lordaeronu, w Dzielnicy Handlowej.', 'Porozmawiaj z Velorą Nitely w Podmieście.', '', '', '', '', '', '', 0),
(1846, 'koKR', 'Piszczele ze Smoczych Paszcz', 'Żeby zrobić brutalne nagolenniki, potrzebuję kilku mocnych piszczeli. Orkowie ze Smoczych Paszcz na Bagniskach mają ładne, grube piszczele. Będę potrzebowała właśnie ich.$B$BAle muszą być mocne. Sprawdzaj piszczele, gdy będziesz je zbierać. Jeśli zdołasz je złamać gołymi rękami, to nie będą dość mocne, żeby z nimi pracować.', 'Przynieś 8 mocnych piszczeli ze Smoczych Paszcz Velorze Nitely w Podmieście.', '', 'Wróć do Velory Nitely w Ruinach Lordaeronu na Polanach Tirisfal.', '', '', '', '', 0),
(1847, 'koKR', 'Brutalne nagolenniki', '', '', '', '', '', '', '', '', 0),
(1882, 'koKR', 'Gospodarstwo Balnira', 'Plagowiska na wschodzie to wynaturzenie. Wymyślone przez Króla Lisza, sączą swoją magię w glebę, wypaczając i zabijając wszystko, co żyje. Choć niszczycielskie siły zarazy mają pewien urok, my, magowie Porzuconych, uważamy, że są nieokiełznane i trzeba je poskromić.$B$BNajpierw jednak musimy zmierzyć, jak daleko rozlała się na Tirisfal. Udaj się do Gospodarstwa Balnira we wschodniej części Tirisfal. W ogrodzie rosną kwiaty – lwie paszcze. Zbierz je i wróć.', 'Przynieś Lwie paszcze Balnira Anastasii Hartwell w Dzielnicy Magów w Podmieście.', '', 'Wróć do Anastasii Hartwell na Polanach Tirisfal.', '', '', '', '', 0),
(1886, 'koKR', 'Tropiciele śmierci', 'Jeśli chcesz dołączyć do Tropicieli śmierci, elitarnej straży lorda Varimathrasa, musisz dowieść swojej wartości.$b$bNie będę cię okłamywał, $n – to zadanie może cię kosztować życie.$b$bMam pewne sprawy do załatwienia. Potrzebuję rzeczy osobistych Astora Hadrena, posłańca kursującego między Srebrzystym Borem a Podmiastem. Sposób ich zdobycia pozostawiam tobie.$b$bIm mniej wiesz o naturze tej sprawy, tym lepiej dla ciebie. Wykonaj zadanie, a powiem ci więcej.', 'Zdobądź List polecający Astora i zanieś go Mennetowi Carkadowi w Dzielnicy Łotrów.', '', 'Wróć do Menneta Carkada w Dzielnicy Łotrów w Podmieście.', '', '', '', '', 0),
(1898, 'koKR', 'Tropiciele śmierci', 'List polecający powinien wystarczyć, by przekonać Androna, że to ty jesteś posłańcem, na którego czeka. Znam Androna – nie ma dość rozumu, żeby być aż tak podejrzliwym.$b$bLord Varimathras podejrzewa, że Andron pomaga jakiejś innej grupie. Chce wiedzieć, co to za organizacja, i potrzebuje na to dowodu.$b$bPorozmawiaj z Andronem i zdobądź te informacje. Znajdziesz go w jego sklepie niedaleko Aptekarium.', 'Porozmawiaj z Andronem Gantem w Podmieście.', '', '', '', '', '', '', 0),
(1899, 'koKR', 'Tropiciele śmierci', 'Księgę rachunkową z informacjami, których szukają twoi mocodawcy, znajdziesz na regale za mną. Dostarcz ją z moimi pozdrowieniami i powiedz im, że wolałbym, żeby nadal przysyłali ciebie – o ile uznają, że warto kontynuować naszą umowę.', 'Przynieś Księgę rachunkową Androna Mennetowi Carkadowi w Dzielnicy Łotrów w Podmieście.', '', 'Wróć do Menneta Carkada w Dzielnicy Łotrów w Podmieście.', '', '', '', '', 0),
(1960, 'koKR', 'Zbadaj sklep alchemika', 'Sklep alchemika Algernona w Aptekarium stał się ogniskiem dziwnych zakłóceń. Po sklepie krążą niewidzialne stworzenia utkane wyłącznie z magii. Musi być jakiś powód i musimy go odkryć!$B$BZbadaj te zakłócenia i schwytaj stworzenia. Weź skrzynię szkatuł i zwój zza moich pleców. Użyj zwoju w sklepie, by stworzenia stały się widoczne, obezwładnij je zaklęciami, a potem rzuć na ziemię szkatułę, by je schwytać. Wróć z napełnionymi szkatułami, pustymi szkatułami i inkantacją.', 'Weź inkantację manifestacji oraz skrzynię szkatuł izolujących, które leżą za Anastasią Hartwell. Przynieś 3 napełnione szkatuły izolujące, skrzynię szkatuł izolujących i inkantację manifestacji Anastasii w Podmieście.', '', 'Wróć do Anastasii Hartwell na Polanach Tirisfal.', '', '', '', '', 0),
(1962, 'koKR', 'Szaty ognia zaklęć', '', '', '', '', '', '', '', '', 0),
(1978, 'koKR', 'Tropiciele śmierci', 'Syndykat? Nigdy bym nie podejrzewał. Zdaje się, że lordowie Alterak upadli nisko przez lata, które minęły od ich zdrady.$b$bLord Varimathras z przyjemnością się o tym dowie, a skoro tak bardzo $gprzyczyniłeś:przyczyniłaś; się do tego odkrycia, wypada, byś to ty $gdostarczył:dostarczyła; mu tę wiadomość.$b$bAch, jak mogłem zapomnieć?$b$bWitaj wśród tropicieli śmierci.', 'Dostarcz księgę rachunkową Androna Varimathrasowi w Sali Mrocznej Pani w Podmieście.', '', '', '', '', '', '', 0),
(1998, 'koKR', 'Fenwick Thatros', 'Lord Varimathras właśnie przysłał mi pismo w sprawie zagrożenia dla Porzuconych, które trzeba natychmiast usunąć. Chodzi o Fenwicka Thatrosa, którego lord Varimathras uważa za przywódcę nieumarłych, którzy zagnieździli się w Srebrzystym Borze.$b$bOd razu pomyślałem o tobie, $n. Wierzę w twoje umiejętności na tyle, że wykonasz tę misję bez najmniejszego błędu.$b$bZ najświeższych raportów tropicieli śmierci ze Srebrzystego Boru wynika, że Thatrosa można znaleźć przy zbutwiałym pomoście nad Jeziorem Lordamere.', 'Zabij Fenwicka Thatrosa i przynieś jego głowę Mennetowi Carkadowi w Dzielnicy Łotrów w Podmieście.', '', 'Wróć do Menneta Carkada w Ruinach Lordaeronu na Polanach Tirisfal.', '', '', '', '', 0),
(2782, 'koKR', 'Sekret Rin\'jiego', 'Tablica jest pokryta znakami trolli Suchokorych. Sekret Rin\'jiego to prawdziwa zagadka...$B$BMożliwe, że wpadło ci w ręce coś bardzo cennego. Równie możliwe jest jednak coś zupełnie przeciwnego. Troll Suchokorych w tarapatach zrobiłby pewnie wszystko, żeby się z nich wywinąć...', 'Oran Wężosplot, znana uczona zajmująca się sprawami trolli Suchokorych, być może zdoła odczytać tablicę. Podobno mieszka w Dzielnicy Magów w Podmieście.', '', '', '', '', '', '', 0),
(2938, 'koKR', 'Jad dla Podmiasta', 'Jad, który $gzebrałeś:zebrałaś; od pajęczej bogini Suchokorych, to nie lada znalezisko! Zdołałem zabić jedną kroplą niemal dwa tuziny królików. Co prawda niektóre były bardzo młode i tak małe, że mieściły się w dłoni, więc ich odporność na toksyny była pewnie niska, ale nie da się zaprzeczyć, że to potężna trucizna!$B$BChciałbym, żeby próbka trafiła do mojego przełożonego, aptekarza Faranella w Aptekarium w Podmieście. Jestem pewien, że zechce ją wypróbować osobiście.', 'Zanieś paczkę Faranella mistrzowi aptekarzowi Faranellowi w Podmieście.', '', '', '', '', '', '', 0),
(2995, 'koKR', 'Linie łączności', 'Stróżówka Quel\'Danil to ośrodek łączności wysokich elfów w Zaziemiu. Ich ambasadorowie starają się nawiązać stosunki z innymi rasami i dzielą się z nimi wiedzą o trollach Suchokorych, które zamieszkują południową część Zaziemia. Wszystkie dokumenty dotyczące tej korespondencji są przechowywane w stróżówce.$B$BNie potrzebujemy, żeby elfy z Wysokiej Doliny zawierały sojusze z innymi, $N.$B$BZniszcz dokumenty z Wysokiej Doliny. Musimy spalić ich linie łączności... dosłownie.', 'Oran Wężosplot z Podmiasta chce, żebyś $gudał:udała; się do Zaziemia i $gspalił:spaliła; akta z Wysokiej Doliny, raport z Wysokiej Doliny i notatki z Wysokiej Doliny.', '', 'Wróć do Oran Wężosplot na Polanach Tirisfal.', 'Spal akta z Wysokiej Doliny', 'Spal notatki z Wysokiej Doliny', 'Spal raport z Wysokiej Doliny', '', 0),
(3341, 'koKR', 'Położyć temu kres', 'Na Pustkowiach leży straszliwa gmatwanina pnączy zwana Kurhanami Brzytwoskórych. Nasze pierwsze obserwacje nie wskazywały na większe zagrożenie, ale ostatnie odkrycia są znacznie poważniejsze...$B$BKolcozwierze z Kurhanów Brzytwoskórych sprzymierzyły się z Plagą. Rządzi nimi teraz lisz zwany Amnennarem Zwiastunem Chłodu, który potęgą swojego ogromnego umysłu kieruje każdym ich ruchem.$B$BAmnennar ma bezpośrednią więź telepatyczną z Ner\'zhulem – musimy ją zerwać, $N. Zwiastun Chłodu musi spotkać swój kres.', 'Andrew Brownell chce, żebyś $gzabił:zabiła; Amnennara Zwiastuna Chłodu i $gprzyniósł:przyniosła; mu jego czaszkę.', '', 'Wróć do Andrew Brownella w Dzielnicy Magów w Podmieście.', '', '', '', '', 0),
(3542, 'koKR', 'Dostawa dla Androna Ganta', 'Moim następnym kontaktem jest Andron Gant. Zwykle przesiaduje w Podmieście... tuż przy Aptekarium.$B$BByło mu nieco łatwiej się rozgadać, gdy chodziło o to, do czego potrzebuje tablicy. Podobno niektórzy magowie z Podmiasta chcą zbadać tajemne zaklęcia, których używali Wysoko Urodzeni. Sądzą, że ta tablica im w tym pomoże. Markri była biegła w przywoływaniu istot, zwłaszcza żywiołaków.$B$BZanieś mu tablicę Markri i wróć do mnie po swoją część nagrody.', 'Zanieś tablicę Markri Andronowi Gantowi w Podmieście.', '', '', '', '', '', '', 0),
(3564, 'koKR', 'Zapłata Androna dla Jedigi', 'Masz... zanieś... <hik> to Jedidze. Powodzenia!', 'Dostarcz notatkę Androna Jedidze w Aszarze.', '', '', '', '', '', '', 0),
(3568, 'koKR', 'Sączące się skażenie', 'Widzisz tę taurenkę za mną – tę, która wygląda, jakby miała się zaraz rozchorować? Była niedawno w Aszarze. Twierdzi, że zraniły ją nagi, kiedy przedzierała się przez Ruiny Eldarath.$B$BGdy odparła kilka z nich, odpoczęła na plaży i napiła się z jednej z pływowych sadzawek. Teraz ma mdłości... i nie tylko.$B$BChciałbym się dowiedzieć, co wypiła. Weź to pudełko – są w nim puste fiolki, które opisałem. Napełnij każdą w innej sadzawce i wracaj.', 'Napełnij wszystkie 4 puste fiolki w pływowych sadzawkach na wybrzeżu Ruin Eldarath w Aszarze, a potem wróć do chemika Cuely\'ego.', '', 'Wróć do chemika Cuely\'ego w Podmieście.', '', '', '', '', 0),
(3569, 'koKR', 'Sączące się skażenie', 'Daj to Thersie. Może ją wyleczy... a może nie. Tak naprawdę dowiemy się dopiero, kiedy to wypije.', 'Daj eliksir Cuely\'ego Thersie Pieśń Wiatru w Podmieście.', '', '', '', '', '', '', 0),
(3570, 'koKR', 'Sączące się skażenie', '', '', '', '', '', '', '', '', 0),
(4133, 'koKR', 'Vivian Lagrave', 'Magini cienia Vivian Lagrave potrzebuje twoich usług. Jest na Bezludziu, w orczej placówce Kargat, i sprawdza pogłoski o pewnym trunku warzonym przez krasnoludy Czarnoryte w Otchłani Czarnej Góry.$B$BPorozmawiaj z Vivian. Czeka na ciebie.', 'Porozmawiaj z maginią cienia Vivian Lagrave w Kargacie.', '', '', '', '', '', '', 0),
(4293, 'koKR', 'Próbka szlamu...', 'Spaczona Knieja to las daleko na północ od Pustkowi, dalej nawet niż Jesionowa Knieja. Wokół tamtejszych sadzawek, naznaczonych dotykiem spaczenia, można spotkać szlamy. Plaga spustoszyła tę okolicę atakami infernali i innej demonicznej magii – podobno szlamy wypełzły spod ziemi właśnie podczas tych ataków.$B$BZbierz próbki szlamów ze Spaczonej Kniei, a za pomocą sprzętu testowego obok mnie utworzymy z nich grupę kontrolną do porównań z innymi próbkami, które zbierzesz.', 'Zbierz próbki szlamu ze Spaczonej Kniei, pobierając je od dowolnych tamtejszych szlamów. Następnie za pomocą sprzętu testowego obok chemika Fuely\'ego w Podmieście sprawdź, które próbki są najbardziej skażone. Przynieś chemikowi Fuely\'emu 5 skażonych próbek ze Spaczonej Kniei.', '', 'Wróć do chemika Fuely\'ego nad Jeziorem Lordamere w Górach Alterak.', '', '', '', '', 0),
(4294, 'koKR', '... i cała partia szlamu', '$GSłyszałeś:Słyszałaś; o Kraterze Un\'Goro, $N? Leży niedaleko pustyni Tanaris i to wspaniałe miejsce: bujne, tętniące życiem, pełne stworzeń i roślin.$B$BTam właśnie musisz się udać. Doszły mnie słuchy, że to miejsce wydaje się zupełnie nietknięte przez obce ręce. Odkrywcy dopiero teraz poznają jego sekrety.$B$BChciałbym zbadać tamtejsze szlamy i mazie. Jeśli to prawda – jeśli nie są skażone – chciałbym zobaczyć, jak takie istoty wyewoluowały.', 'Zbierz próbki szlamu z Un\'Goro, pobierając je od dowolnych szlamów w Kraterze Un\'Goro. Następnie za pomocą sprzętu testowego obok chemika Fuely\'ego w Podmieście sprawdź, które próbki są najczystsze. Przynieś chemikowi Fuely\'emu 5 czystych próbek z Krateru Un\'Goro.', '', 'Wróć do chemika Fuely\'ego nad Jeziorem Lordamere w Górach Alterak.', '', '', '', '', 0),
(4642, 'koKR', 'Stopienie wpływów', 'Oto zamknięty szlam, który uzyskałem z próbek ze Spaczonej Kniei. Zabierz pojemnik do Krateru Un\'Goro i znajdź czysty szlam... odmiana pierwotna świetnie się nada. Gdy podejdziesz dość blisko, wypuść szlam z pojemnika i zobaczmy, co te dwa o sobie pomyślą.$B$BKiedy eksperyment się zakończy, przynieś mi próbkę tego, co z nich zostanie. Będę na ciebie czekać tutaj, w Aptekarium.', 'Przynieś połączoną próbkę szlamu chemikowi Fuely\'emu w Podmieście.', '', 'Wróć do chemika Fuely\'ego nad Jeziorem Lordamere w Górach Alterak.', '', '', '', '', 0),
(4769, 'koKR', 'Vivian Lagrave i tablica z mrocznego kamienia', 'Vivian Lagrave przysłała mi wiadomość z Kargatu na Bezludziu. Na podstawie swoich badań uważa, że w Iglicy Czarnej Góry jest starożytny tekst, który przydałby się w naszych badaniach. Aby to potwierdzić, potrzebuje kogoś, kto wydobędzie ten tekst z iglicy. Niełatwe zadanie.$B$BJeśli cię to interesuje, porozmawiaj z Vivian w Kargacie.', 'Porozmawiaj z maginią cienia Vivian Lagrave.', '', '', '', '', '', '', 0),
(5049, 'koKR', 'Blues Jeremiaha', 'Z tego, co udało mi się zebrać, wynika, że osoba, której szukasz – i zamierzony odbiorca przesyłki – to Jeremiah Payson, handlarz karaluchami z Podmiasta.$B$BZawsze uważałem, że do sprzedawania... karaluchów trzeba mieć szczególny dar. Bez wątpienia odbywasz teraz iście epicką wędrówkę, $N. Nie będę ci przeszkadzał w dziele przemieniania świata. Pozwól mi jednak mieć swój udział w twoim opus magnum i zdradzić, że znajdziesz go niedaleko banku – płaszczy się, jak przystało, pod jednym z pomostów.', 'Odnajdź Jeremiaha Paysona w Podmieście i sprawdź, czy to rzeczywiście Jeremiah Felstone. Jeśli tak, może zechce przyjąć paczkę, którą przygotowała dla niego Janice Felstone.', '', '', '', '', '', '', 0),
(5961, 'koKR', 'Czempion Królowej Banshee', 'Bardzo mnie cieszy, gdy zaprawieni w boju przyłączają się do naszej sprawy. Z każdym dniem rośniemy w liczbę i siłę. Może jesteś $ggotów:gotowa; sprawdzić swój hart, $N?$B$BJednym z pierwszych moich czempionów był Nathanos, dziś zwany Heroldem Plagi. Niewielu w naszych szeregach dorównuje mu oddaniem i zapałem.$B$BOdszukaj go na Wschodnich Plagowiskach. Mieszka w Zagrodzie Marrisów, a od czasu do czasu przemierza spustoszone pustkowia i zabija każdego sługę Plagi i każdą szumowinę z Przymierza, która stanie mu na drodze.', 'Porozmawiaj z Nathanosem Heroldem Plagi na Wschodnich Plagowiskach. Podobno zamieszkał w Zagrodzie Marrisów.$B', '', '', '', '', '', '', 0),
(6003, 'koKR', '<nyi> <txt> Zielony z zazdrości', '', '', '', '', '', '', '', '', 0),
(6144, 'koKR', 'Wezwanie dowództwa', 'Przyszedł rozkaz, $N. Sam Bragor Krwawa Pięść zażądał, bym odesłał do Podmiasta moich najbardziej „zdolnych” agentów na potrzeby wyjątkowo delikatnej operacji taktycznej.$B$BNiestety moi najbardziej zdolni agenci zginęli ponad trzy lata temu. W ich miejsce mam zbieraninę bezmózgiej hołoty.$B$B<Nathanos patrzy na ciebie lodowatym wzrokiem.>$B$BNatychmiast udaj się do Podmiasta i zamelduj się u Bragora Krwawej Pięści. Nie przynieś mi wstydu, $N!', 'Udaj się do Podmiasta i porozmawiaj z Bragorem Krwawą Pięścią.', '', '', '', '', '', '', 0),
(6145, 'koKR', 'Karmazynowy Kurier', 'Tak jak ciało nie przeżyje bez głowy, tak głowa nie przeżyje bez ciała. Obrona dowództwa Szkarłatnej Krucjaty w Stratholmie jest niemal nie do przebicia. Musimy więc odciąć głowie ciało.$B$BMoi tropiciele śmierci zbierają informacje o działaniach Krucjaty poza Stratholmem. Każdego dnia z jej centralnego dowództwa do Dłoni Tyra wysyłany jest raport. Ten raport jest kluczem, $N! Odnajdź Karmazynowego Kuriera i odbierz mu raport. Zanieś go Nathanosowi.', 'Wróć na Wschodnie Plagowiska i wytrop Karmazynowego Kuriera. Zabij kuriera i odbierz mu rozkaz Wielkiego Krzyżowca.$B$BZanieś rozkaz Nathanosowi Heroldowi Plagi po dalsze instrukcje.', '', 'Wróć do Nathanosa Herolda Plagi w Zagrodzie Marrisów na Wschodnich Plagowiskach.', '', '', '', '', 0),
(6322, 'koKR', 'Michael Garrett', 'Zapakowałem zapasy dla Grobowiska do tej skrzynki. Jeśli $godwiedziłeś:odwiedziłaś; już Grobowisko i $grozmawiałeś:rozmawiałaś; z tamtejszym treserem nietoperzy, możesz polecieć do niego na nietoperzu.$B$BPorozmawiaj z treserem nietoperzy w Podmieście, Michaelem Garrettem. Załatwi ci nietoperza do Grobowiska.', 'Zanieś skrzynkę Gordona Michaelowi Garrettowi.', '', '', '', '', '', '', 0),
(6323, 'koKR', 'Lot do Podmiasta', 'Za niewielką opłatą jeden z moich nietoperzy zaniesie cię do Podmiasta. Porozmawiaj ze mną znowu, gdy będziesz $ggotów:gotowa;, a zorganizujemy ci transport.$B$BGordona Wendhama znajdziesz w Dzielnicy Handlowej Podmiasta. W tej samej dzielnicy wyląduje mój nietoperz.', 'Wykup lot na nietoperzu do Podmiasta u tresera nietoperzy Karosa Razoka, a następnie zanieś rozkaz Podriga Gordonowi Wendhamowi w Podmieście.', '', '', '', '', '', '', 0),
(6324, 'koKR', 'Powrót do Podriga', 'Treserem nietoperzy w Grobowisku jest Karos Razok. Jeśli już go $gpoznałeś:poznałaś;, mogę ci dać nietoperza, który zaniesie cię z powrotem do niego.$B$BNasze nietoperze zawsze polecą do Podmiasta, ale żeby latać w bardziej odległe miejsca, jeździec musi najpierw je odwiedzić i porozmawiać z tamtejszym treserem nietoperzy.$B$B$GPoznałeś:Poznałaś; Karosa w Grobowisku, więc możesz już tam latać nietoperzami. Porozmawiaj ze mną znowu, gdy będziesz $ggotów:gotowa;.', 'Wykup lot na nietoperzu do Grobowiska u tresera nietoperzy Michaela Garretta, a następnie zanieś skrzynkę Gordona strażnikowi śmierci Podrigowi w Grobowisku.', '', '', '', '', '', '', 0),
(6628, 'koKR', 'Próba wiedzy', 'A więc znów nadeszła ta chwila. Jako $guczeń:uczennica; wiedzy $gwykazałeś:wykazałaś; się wielką wytrwałością, podejmując się mojego zadania.$B$BTeraz zadam ci swoje pytanie. Jeśli jesteś $ggotów:gotowa;, porozmawiaj ze mną znowu i nie spiesz się, $N – nikt cię nie pogania.', 'Odpowiedz poprawnie na pytanie Parquala Fintallasa, a potem porozmawiaj z nim ponownie. Będzie czekał w Podmieście, aż będziesz $ggotów:gotowa;.', 'Odpowiedz poprawnie na pytanie Parquala Fintallasa', 'Wróć do Parquala Fintallasa nad Jeziorem Lordamere w Górach Alterak.', '', '', '', '', 0),
(8273, 'koKR', 'Wdzięczność Oran', '', '', '', '', '', '', '', '', 0),
(8648, 'koKR', 'Nestor Mroczny Rdzeń', '', '', '', '', '', '', '', '', 0),
(8980, 'koKR', 'Ocena Zinge', 'A to niespodzianka. Wygląda na to, że Fenstad jednak mógł trafić na jakiś trop. Znalazłam ślady substancji używanych w miksturach kontroli umysłu.$b$bZdarza się, że perfumy zawierają ich odrobinę, ale kilka składników, które wykryłam... To poważna alchemia, na miarę umiejętności członka Królewskich Zakładów Chemicznych.', 'Wróć do Fenstada Argyle\'a przed bankiem w Podmieście.', '', '', '', '', '', '', 0),
(9177, 'koKR', 'Podróż do Podmiasta', 'To zdumiewające! Wygląda na to, że to podarunek dla Lady Sylwany Bieżywiatr od jej siostry, Allerii!$B$BMusisz natychmiast zanieść go jej do Podmiasta! Pani przyjmuje w Królewskim Kwartale.$B$BAby się tam dostać, użyj kuli translokacji w Wewnętrznym Sanktuarium Iglicy Słonecznej Furii w Srebrnej Lunie – przeniesie cię do Podmiasta. Na miejscu zjedź windą w dół, do właściwego miasta. Jeśli potrzebujesz pomocy w odnalezieniu Królewskiego Kwartału, zajrzyj do map.', 'Zanieś naszyjnik Pani Lady Sylwanie Bieżywiatr w Królewskim Kwartale w Podmieście.', '', '', '', '', '', '', 0),
(9180, 'koKR', 'Podróż do Podmiasta', 'To zdumiewające! Wygląda na to, że to podarunek dla Lady Sylwany Bieżywiatr od jej siostry, Allerii!$B$BMusisz natychmiast zanieść go jej do Podmiasta! Pani przyjmuje w Królewskim Kwartale.$B$BAby się tam dostać, użyj kuli translokacji w Wewnętrznym Sanktuarium Iglicy Słonecznej Furii w Srebrnej Lunie – przeniesie cię do Podmiasta. Na miejscu zjedź windą w dół, do właściwego miasta. Jeśli potrzebujesz pomocy w odnalezieniu Królewskiego Kwartału, zajrzyj do map.', 'Zanieś naszyjnik Pani Lady Sylwanie Bieżywiatr w Królewskim Kwartale w Podmieście.', '', '', '', '', '', '', 0),
(9189, 'koKR', 'Przesyłka do Grobowiska', '$GPoruszyłeś:Poruszyłaś; serce Pani, choć już ono nie bije.$B$BMam jednak instrukcje, które trzeba dostarczyć do Grobowiska w Srebrzystym Borze. Reprezentuje tam nas wobec Porzuconych doradca Sorrelon.$B$BNajkrótsza droga – pomijając ich latające nietoperze – to wyjść z Podmiasta i ruszyć drogą na południe. Kieruj się drogowskazami. Trafienie tam nie powinno sprawić trudności. Przygotuj się jednak: samo Grobowisko to zrujnowana krypta.$B$BCi Porzuceni to doprawdy dziwne istoty.', 'Dostarcz zapieczętowane rozkazy sin\'dorei doradcy Sorrelonowi w Grobowisku w Srebrzystym Borze.', '', '', '', '', '', '', 0),
(9310, 'koKR', 'Słaby nekrotyczny kryształ', 'Przy zwłokach powalonego truposza znajdujesz kryształ, który słabo promieniuje nekrotyczną energią.', 'Zanieś słaby nekrotyczny kryształ porucznikowi Rukagowi na dziedzińcu Podmiasta.', '', '', '', '', '', '', 0),
(9425, 'koKR', 'Zamelduj się w Smolnym Młynie', 'Ach, dobrze cię tu widzieć, $N! Mam zadanie w sam raz dla ciebie.$B$BJako nowi członkowie Hordy musimy wspierać jej wysiłki i pomagać w jej kłopotach. Wtedy chętniej pomoże nam w naszych.$B$BUdaj się na południowy wschód, do miasteczka Porzuconych, Smolnego Młyna w Międzygórzu. Po przybyciu zgłoś się do doradczyni Duskingdawn.', 'Udaj się do Smolnego Młyna w Międzygórzu i porozmawiaj z doradczynią Duskingdawn.', '', '', '', '', '', '', 0),
(9621, 'koKR', 'Wysłannik do Hordy', 'Nasi potencjalni nowi sojusznicy wątpili w nasze możliwości. Na co mielibyśmy im się przydać, skoro uchodziliśmy za niezdolnych do uporania się z własnymi problemami we własnym domu?$B$BTo zmienia wszystko. Nikt już nie podda w wątpliwość naszej potęgi. Będziemy mogli przystąpić do Hordy jako równi.$B$BZanieś ten list Sylwanie, władczyni Porzuconych. Już stoi po naszej stronie, ale wieść o śmierci Dar\'Khana zabrzmi w jej uszach jak muzyka. Przygotuj się na długą podróż, $N. Jeśli wszystko pójdzie dobrze, pośle cię do Orgrimmaru.', 'Zanieś list od Lor\'themara Therona Lady Sylwanie Bieżywiatr w Podmieście, stolicy Porzuconych na Polanach Tirisfal.', '', '', '', '', '', '', 0),
(9812, 'koKR', 'Wysłannik do Hordy', 'Nasi potencjalni nowi sojusznicy wątpili w nasze możliwości. Na co mielibyśmy im się przydać, skoro uchodziliśmy za niezdolnych do uporania się z własnymi problemami we własnym domu?$B$BTo zmienia wszystko. Nikt już nie podda w wątpliwość naszej potęgi. Będziemy mogli przystąpić do Hordy jako równi.$B$BZanieś ten list Sylwanie, władczyni Porzuconych. Już stoi po naszej stronie, ale wieść o śmierci Dar\'Khana zabrzmi w jej uszach jak muzyka. Przygotuj się na długą podróż, $N. Jeśli wszystko pójdzie dobrze, pośle cię do Orgrimmaru.', 'Zanieś list od Lor\'themara Therona Lady Sylwanie Bieżywiatr w Podmieście, stolicy Porzuconych na Polanach Tirisfal.', '', '', '', '', '', '', 0),
(9833, 'koKR', 'Linie łączności', 'Jednym z powodów, dla których Ikuti przyprowadził nas na Moczary Zangarskie, była chęć nawiązania łączności między draenei a Telaar w Nagrandzie, rodzinnym miastem Kurenai. Żeby posłańcy mogli szybko przemieszczać się między Telaar a Telredorem, drogi muszą być bezpieczne.$B$BW drodze tutaj raz po raz atakowały nas bagiennokłe siekacze. Zdołaliśmy je odeprzeć, ale dla samotnego posłańca byłyby groźnym przeciwnikiem. Przetrzebienie ich pomoże zapewnić bezpieczeństwo naszym posłańcom.', 'Puluu w Przystani Orebor chce, żebyś $gzabił:zabiła; 12 bagiennokłych siekaczy.', '', 'Wróć do Puluu w Przystani Orebor na Moczarach Zangarskich.', '', '', '', '', 0),
(12787, 'koKR', 'Podmiasto', 'Zaraza zombie okazała się błogosławieństwem w przebraniu. Szukając lekarstwa, dowiedzieliśmy się tak wiele o Pladze i jej zarazie. Nasze badania dały nam broń przeciwko niej. Broń i narzędzia...$B$BWeź to – to głowa zombie, częściowo wyleczona z zarazy zastrzykiem ze związku, który uzyskaliśmy dzięki naszym niedawnym odkryciom. Dostarcz ją mistrzowi aptekarzowi Faranellowi. Mam dla niego listę eksperymentów, które powinien na niej przeprowadzić.', 'Wielki aptekarz Putress prosi o przekazanie Podwójnie zarażonego mózgu mistrzowi aptekarzowi Faranellowi w Podmieście.', '', 'Wróć do mistrza aptekarza Faranella nad Jeziorem Lordamere w Górach Alterak.', '', '', '', '', 0),
(14349, 'koKR', 'Wezwanie dowództwa', 'Przyszedł rozkaz, $N. Sama Sylwana zażądała, żebym odesłał moich najbardziej „zdolnych” agentów do Podmiasta na wyjątkowo delikatną operację taktyczną.$B$BNiestety, moi najzdolniejsi agenci zginęli ponad trzy lata temu. W ich miejsce mam zbieraninę bezmózgiej hołoty.$B$B<Nathanos mierzy cię lodowatym spojrzeniem.>$B$BNatychmiast udaj się do Podmiasta i zamelduj się u Mrocznej Pani. Nie przynieś mi wstydu, $N!', 'Udaj się do Podmiasta i porozmawiaj z lady Sylwaną Bieżywiatr.', '', '', '', '', '', '', 0),
(14350, 'koKR', 'Karmazynowy Kurier', 'Nie możemy uderzyć wprost na dowództwo Szkarłatnej Krucjaty – jest zbyt dobrze strzeżone. Ale do celu prowadzi więcej niż jedna droga. Bez swoich głównych sił będą niczym.$B$BTropiciele śmierci zbierają informacje o działaniach Krucjaty pod Stratholmem. Każdego dnia z ich centralnego dowództwa do Dłoni Tyra wysyłany jest raport. Ten raport to klucz! Znajdź Karmazynowego kuriera i odbierz mu ten raport. Zanieś go Nathanosowi.', 'Wróć na Wschodnie Plagowiska i wytrop Karmazynowego Kuriera. Zabij kuriera i odbierz mu rozkaz Wielkiego Krzyżowca.$B$BZanieś rozkaz Nathanosowi Heroldowi Plagi po dalsze instrukcje.', '', 'Wróć do Nathanosa Herolda Plagi w Zagrodzie Marrisów na Wschodnich Plagowiskach.', '', '', '', '', 0),
(14351, 'koKR', 'Bitwa o Międzygórze', 'Ponieważ w Bitwie o Międzygórze $gwalczyłeś:walczyłaś; z takim męstwem i wytrwałością, napisałam tę pochwałę, sławiącą twoje bohaterskie czyny w walce, by naczelne dowództwo mogło je docenić.$b$bZanieś tę zapieczętowaną pochwałę Bragorowi Krwawej Pięści w Podmieście. Idź z dumą, $N.', 'Zanieś Zapieczętowaną pochwałę Darthalii Bragorowi Krwawej Pięści w Podmieście.', '', 'Wróć do Bragora Krwawej Pięści w Królewskim Kwartale w Podmieście.', '', '', '', '', 0),
(14352, 'koKR', 'Bezbożny sojusz', 'Moja Pani,$B$BDoskonale wiesz, co oferujemy. Okazja, by zająć Pustkowia i ziemie za nimi, jest ogromna. W zamian prosimy jedynie o Twoją pomoc. A przez pomoc rozumiemy wyłącznie to, że pozwolisz nam swobodnie działać na tym obszarze.$B$BProszę, pozwól nam omówić to szerzej. Mamy wielką moc i chętnie podzielimy się nią z tymi, którzy są dość mądrzy, by do nas dołączyć. Na razie pozostanę przed Kurhanami Brzytwoskórych.$B$BZ wyrazami szacunku$BAmbasador Malcin', 'Zanieś Mały zwój Bragorowi Krwawej Pięści w Podmieście.', '', 'Wróć do Bragora Krwawej Pięści w Królewskim Kwartale w Podmieście.', '', '', '', '', 0),
(14353, 'koKR', 'Bezbożny sojusz', 'Podobno ten Malcin czeka przed Kurhanami Brzytwoskórych. Nie ma dyskusji – musi zginąć.$b$bMoi ludzie w Orgrimmarze donoszą, że ich zwiadowcy znaleźli tam ślady zarazy. Kolcozwierze też wyglądają na zarażone; są przez to znacznie silniejsze. Cokolwiek Plaga tam knuje, trzeba to zakończyć. Natychmiast.$b$bZnajdź tego Malcina i zabij go. Wróć tu, kiedy będzie martwy.', 'Przynieś Głowę ambasadora Malcina Bragorowi Krwawej Pięści w Podmieście.', '', 'Wróć do Bragora Krwawej Pięści w Królewskim Kwartale w Podmieście.', '', '', '', '', 0),
(14355, 'koKR', 'W głąb Szkarłatnego Klasztoru', 'Póki tu stacjonuję, jednym z moich obowiązków jest pomagać Porzuconym w pilnowaniu ich granic – i właśnie tym, $N, zajmiesz się dla mnie.$b$bJa może i żyję, i oddycham, ale Szkarłatna Krucjata wyrżnie moich ludzi równie szybko jak nieumarłych. To tutaj problem, i to duży, a ty coś z nim zrobisz.$b$bIdź do Klasztoru i zabij nadinkwizytorkę Białowłosą oraz jej zastępców.', 'Zabij nadinkwizytorkę Białowłosą, szkarłatnego komandora Mograine\'a, Heroda – Szkarłatnego czempiona – oraz tresera ogarów Lokseya, a potem wróć do Bragora Krwawej Pięści w Podmieście.', '', 'Wróć do Bragora Krwawej Pięści w Królewskim Kwartale w Podmieście.', '', '', '', '', 0),
(14356, 'koKR', 'Moc niszczenia...', 'Słuchaj uważnie, $N.$b$bMożesz o tym nie wiedzieć, ale Orgrimmar ma problem. W głębi Rozpadliny Wściekłego Ognia sekta Rady Cieni, zwana Palącym Ostrzem, prowadzi swoje złowrogie dzieło. To głównie orkowie, a nie mogę powierzyć poufnych informacji tamtejszym siepaczom. Tu wkraczasz ty.$b$bPowinni mieć przy sobie dwie księgi. Nie chcę, żeby zostały w rękach Palącego Ostrza – ani żeby trafiły do Porzuconych. Przynieś je prosto do mnie.', 'Przynieś księgi „Zaklęcia cienia” i „Inkantacje z Otchłani” Bragorowi Krwawej Pięści w Podmieście.', '', 'Wróć do Bragora Krwawej Pięści w Królewskim Kwartale w Podmieście.', '', '', '', '', 0),
(14418, 'koKR', 'Tropiciele śmierci', 'Syndykat? Nigdy bym nie podejrzewał. Zdaje się, że lordowie Alterak upadli bardzo nisko od czasu swojej zdrady.$b$bHawkins ucieszy się z tych wieści, a skoro tak bardzo $gprzyczyniłeś:przyczyniłaś; się do tego odkrycia, wypada, byś to ty mu je $gprzekazał:przekazała;.$b$bAch, jak mogłem zapomnieć?$b$bWitaj wśród Tropicieli śmierci.', 'Dostarcz Księgę rachunkową Androna Alericowi Hawkinsowi w Sali Mrocznej Pani w Podmieście.', '', 'Wróć do Alerica Hawkinsa w Sali Mrocznej Pani w Podmieście.', '', '', '', '', 0),
(14419, 'koKR', 'Tropiciele śmierci', 'List polecający powinien wystarczyć, by przekonać Androna, że to ty jesteś posłańcem, na którego czeka. Znam Androna – nie ma dość rozumu, żeby być aż tak podejrzliwym.$b$bNasz przywódca podejrzewa, że Andron pomaga jakiejś innej grupie. Chce wiedzieć, co to za organizacja, i potrzebuje na to dowodu.$b$bPorozmawiaj z Andronem i zdobądź te informacje. Znajdziesz go w jego sklepie niedaleko Aptekarium.', 'Porozmawiaj z Andronem Gantem w Podmieście.', '', 'Wróć do Androna Ganta w Aptekarium w Podmieście.', '', '', '', '', 0),
(14420, 'koKR', 'Tropiciele śmierci', 'Jeśli chcesz dołączyć do Tropicieli śmierci, elitarnej straży Mrocznej Pani, musisz dowieść swojej wartości.$b$bNie będę cię okłamywał, $n – to zadanie może cię kosztować życie.$b$bMam pewne sprawy do załatwienia. Potrzebuję rzeczy osobistych Astora Hadrena, posłańca kursującego między Srebrzystym Borem a Podmiastem. Sposób ich zdobycia pozostawiam tobie.$b$bIm mniej wiesz o naturze tej sprawy, tym lepiej dla ciebie. Wykonaj zadanie, a powiem ci więcej.', 'Zdobądź List polecający Astora i zanieś go Mennetowi Carkadowi w Dzielnicy Łotrów.', '', 'Wróć do Menneta Carkada w Dzielnicy Łotrów w Podmieście.', '', '', '', '', 0),
(14421, 'koKR', 'Tropiciele śmierci', 'Księgę rachunkową z informacjami, których szukają twoi mocodawcy, znajdziesz na regale za mną. Dostarcz ją z moimi pozdrowieniami i powiedz im, że wolałbym, żeby nadal przysyłali ciebie – o ile uznają, że warto kontynuować naszą umowę.', 'Przynieś Księgę rachunkową Androna Mennetowi Carkadowi w Dzielnicy Łotrów w Podmieście.', '', 'Wróć do Menneta Carkada w Dzielnicy Łotrów w Podmieście.', '', '', '', '', 0),
(24613, 'koKR', 'Podarek dla Królowej Banshee', 'Chcesz zrobić Uroczą bransoletkę z talizmanami dla Królowej Banshee? Na pewno będzie zachwycona.$B$BMasz już Zestaw kolekcjonera uroczych talizmanów?', 'Wręcz Uroczą bransoletkę z talizmanami lady Sylwanie Bieżywiatr w Podmieście.', '', 'Wróć do lady Sylwany Bieżywiatr.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(232, 'koKR', 'Ach, Zinge potrzebuje zestawu, tak? Smuci mnie, że Zinge nie raczy mnie zaszczycić swoją słodką obecnością.$B$BNiech będzie, zaraz przygotuję dla ciebie zestaw.', 0),
(238, 'koKR', 'Dobrze. Miło mi pracować z kimś, kto szczyci się tym, że nie marnuje mojego czasu.$b$bKiedy wprowadzę w tym zestawie kilka poprawek, będziesz $ggotowy:gotowa; ruszyć w teren. Posłuży ci do zebrania danych kluczowych dla naszego zadania.$b$bDokończenie przeróbek zajmie mi tylko chwilę. W międzyczasie zastanów się, co chcesz zabrać ze sobą na pustynię.$b$bTak, powiedziałam: na pustynię.', 0),
(243, 'koKR', 'Ach, nasze źródła zasilania model 4711-FTZ! Zwykle napędzamy nimi studnie, ale DZIĘKI TYM PODŁYM KOCZOWNIKOM mamy ich teraz nadmiar.$b$bJasne, załatwię ci źródło zasilania do tego niecnego eksperymentu naukowego, który próbujesz przede mną ukryć. Ale za darmo nie będzie, $gkolego:koleżanko;. W Gadżetonie nic nie ma za darmo.', 0),
(357, 'koKR', 'Bardzo dobrze, $N. Przestudiuję tę księgę i ustalę, kim jest ten lisz. Dobrze $gprzysłużyłeś:przysłużyłaś; się swojej królowej.$B$B<Bethor otwiera księgę i wpatruje się w jej jarzące się stronice...>$B$BZdumiewające! Księga, którą $gprzyniosłeś:przyniosłaś;, należy do nikogo innego jak Gunthera Arcanusa!$B$BZa życia Gunther był biegłym nekromantą. Przed Zarazą byliśmy przyjaciółmi i towarzyszami broni. A sądząc po jego księdze, po śmierci stał się jeszcze potężniejszy.$B$BJego umiejętności byłyby dla nas wielkim darem.', 0),
(444, 'koKR', 'Ta substancja jest przesiąknięta potężnymi zaklęciami, niektórych nie widziałem od bardzo, bardzo dawna...$b$bChwileczkę – muszę rzucić zaklęcie wieszczenia...', 0),
(446, 'koKR', 'Ten zwój jest przesiąknięty potężną magią. Nigdy nie używałem takich sił w miksturze... To będzie potężny wywar. Powinien ci dobrze posłużyć, jeśli zaatakujesz Thule\'a w jego twierdzy na Wyspie Fenris.', 0),
(447, 'koKR', 'Jak miło ze strony aptekarza Renferrela, że cię do mnie przysłał, $N. Te próbki z pewnością przydadzą się naszej sprawie. Natychmiast zacznę badać ich właściwości toksyczne i zakaźne.', 0),
(450, 'koKR', 'Dziennik aptekarza Berarda! Ależ z ciebie $gśmiałek:śmiałkini;, $N. Zobaczmy, czym zajmował się Berard, zanim oszalał...', 0),
(451, 'koKR', 'Utrata Berarda to dla Królewskich Zakładów Chemicznych ciężki cios. Ale dzięki twojej ciężkiej pracy i sumiennym badaniom aptekarza Renferrela odkrycia Berarda wciąż posłużą sprawie Mrocznej Pani.$b$bJesteśmy o krok od czegoś wielkiego, $N. Gdyby nie twoja biegłość w walce, próbowałbym cię zwerbować do Zakładów.', 0),
(491, 'koKR', '...co to jest? Thule miał naszą Plecioną różdżkę? Myślałem, że przepadła, kiedy nasza przyjaźń się rozpadła, a on stanął po stronie Króla Lisza!$b$bNie mógł uwolnić jej mocy, bo wyczułbym to. I dobrze, że jej nie użył...$b$bTo wspaniałe znalezisko. Masz moją wdzięczność, $N, i otrzymasz nagrodę.', 0),
(495, 'koKR', 'Przysłała cię Sharlindra? No dobrze. Przekonasz się, że nie tracę czasu na czcze pogawędki.$B$BMug\'Thol jest utrapieniem, a my rozprawimy się z nim szybko, dokładnie i bez niespodzianek.', 0),
(513, 'koKR', 'Przysłał cię aptekarz Lydon? Ach, czemu od razu nie mówisz!$b$bMimo ponurego usposobienia aptekarz Lydon jest jednym z naszych najbardziej oddanych i biegłych członków.$b$bPoczciwiec przysyła Kompozyt z błotopyska! Już wiem, co knuje nasz przyjaciel w Międzygórzu. I podoba mi się jego tok myślenia. Mroczna Pani byłaby pod wielkim wrażeniem jego postępów w pracach nad nową zarazą.', 0),
(515, 'koKR', 'Ten eksperyment tak mnie ekscytuje, że aż kręci mi się w głowie! Bardzo mi $gpomogłeś:pomogłaś;, $N. Razem zasiejemy w tej krainie śmierć i choroby!', 0),
(521, 'koKR', 'A więc to jest relikt, dzięki któremu ogr wymknął się woli Mrocznej Pani...$b$bDziwne, że coś tak prostego może dzierżyć tak wielką moc. I wpaść w tak niezdarne łapy. Dobra robota, $N. Dostarczę koronę lady Sylwanie i dopilnuję, by usłyszała o twoim wyczynie.', 0),
(530, 'koKR', 'Ach, dobrze. Te dłonie zabiły moją żonę, Deliah. Zemsta za jej śmierć była moją jedyną troską, a ty $gbyłeś:byłaś; narzędziem tej zemsty.$b$bMasz, weź pierścień, który $gzwróciłeś:zwróciłaś; mi wcześniej. Deliah jest dla mnie martwa od tak dawna, że jej pierścień to błyskotka, której nie chcę już trzymać. Zamiast niego zachowam te dłonie na pamiątkę zdrady przyjaciela.', 0),
(728, 'koKR', 'Bądź $gdyskretniejszy:dyskretniejsza; ze swoimi znakami, $N. Są tacy, którzy nie wierzą w słuszność naszej przysięgi.$B$BI są tacy, którzy chcieliby naszej klęski, gdyby się o nas dowiedzieli.$B$BMusimy zawsze być ostrożni. I czujni. I cierpliwi.', 0),
(736, 'koKR', 'Jestem pod wrażeniem! Skoro $gzdobyłeś:zdobyłaś; te relikwie, masz wielkie umiejętności albo wielkie szczęście. Tak czy inaczej, jesteś dla nas cennym nabytkiem.', 0),
(864, 'koKR', 'Natychmiast przeanalizuję te dane. Być może szaleństwo Keevera okaże się jednak moim geniuszem.$B$BCo do ciebie... jesteś mi $gprzydatny:przydatna;, a tych, którzy pozostają przydatni, nagradzam całkiem hojnie. Weź ten przedmiot, te monety, a przede wszystkim moje podziękowania.$B$BZaglądaj do mnie od czasu do czasu. Założę się, że nasza współpraca nad tym projektem jeszcze się nie skończyła.', 0),
(1013, 'koKR', 'Bardzo dobrze. Ta księga ładnie uzupełni moje zbiory dzieł Ura. Jego wiedza była wielka, ale sumienie nie dopuszczało go do prawdziwej potęgi. Toteż gdy nadeszła Plaga i jego siła została wystawiona na próbę, zawiodła.$B$BMy, Porzuceni, nie możemy sobie pozwolić na taką słabość, jeśli mamy przetrwać...', 0),
(1109, 'koKR', 'Wspaniale! Właśnie takiego początku potrzebowaliśmy, $N.', 0),
(1113, 'koKR', 'Mój ty, cóż za obfitość krwawych flaków mi $gprzyniosłeś:przyniosłaś;, $N! Twoje starania były przednie!', 0),
(1159, 'koKR', 'Przysłał cię Braug? Niemożliwe.$b$b<Parqual mierzy cię wzrokiem od stóp do głów.>$b$b$GStawiłeś:Stawiłaś; czoła Dor\'Danil, $gskoczyłeś:skoczyłaś; na wiarę, $gwalczyłeś:walczyłaś; z potężnym żywiołakiem i go $gpokonałeś:pokonałaś;? Phi! Pewnie jesteś $gzwykłym oszustem:zwykłą oszustką; – jakimś poszukiwaczem przygód, który podsłuchał rozmowę w tawernie. A teraz myślisz, że masz to, czego trzeba, by przejść moją próbę. Niech i tak będzie... $N.', 0),
(1160, 'koKR', 'To księga, po którą cię wysłałem.$b$b<Parqual powoli przesuwa dłonią po okładce, wpatrując się w nią.>$b$bA więc chcesz pytania, by dowieść, że twój umysł jest równie silny jak ciało i duch. Jeśli dość długo $gstudiowałeś:studiowałaś; tę księgę, zadam ci pytanie i będziesz mieć te próby za sobą!', 0),
(1164, 'koKR', 'Stoisz przede mną jako uosobienie zemsty, a ja kłaniam ci się w podzięce.$B$BSkoro ta krowa nie żyje, a ich nasienie nie rozpleni się już po obliczu Azeroth, mogę poświęcić siły czemuś bardziej opłacalnemu. Mam nadzieję, że $gobrabowałeś:obrabowałaś; ich gospodarstwo, kiedy już z nimi $gskończyłeś:skończyłaś;.', 0),
(1359, 'koKR', 'Ach tak, próbki serc, o których mówił Renferrel. Nie mogę się doczekać eksperymentów z nimi... Królewskie Zakłady Chemiczne zawsze interesują się odkryciem nowych rodzajów toksyn.', 0),
(1394, 'koKR', 'Ach, $N. Dawno nie $gprzekroczyłeś:przekroczyłaś; progu mojego domu. Zdaje się, że minęło wiele księżyców, odkąd $gwykonałeś:wykonałaś; swój pierwszy skok, który wprowadził cię na tę ścieżkę.$b$bA teraz wracasz do mnie $gsilniejszy:silniejsza; niż kiedyś... bardziej $goświecony:oświecona;. To mnie cieszy. I należy ci się sprawiedliwa nagroda za to, że $gprzeszedłeś:przeszłaś; moje próby do końca.', 0),
(1471, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N. Teraz przekażę ci zaklęcie służące do przywoływania wędrowca Pustki.$B$BMoc, którą przeciw tobie rozpętał, jest teraz twoja i to ty nią rozkazujesz. Używaj jej mądrze.', 0),
(1472, 'koKR', 'Przysłał cię Carendin? Sithel, zatem.$b$bNie lekceważ mnie dlatego, że straciłem wzrok. Teraz widzę rzeczy, które kryją się pod powierzchnią, z jasnością, jakiej nigdy nie znałem. To, co kiedyś uważałem za klątwę, jest teraz darem.', 0),
(1473, 'koKR', 'Ach, doskonale. Najpewniej Perrine nie miał pojęcia o prawdziwej mocy tej stęchłej księgi, którą nam ukradł.$B$BWięcej nie wypadnie z naszych rąk. Przyjrzyj się, $N, budowie tego zaklęcia i temu, jak należy kierować twoją mocą.', 0),
(1474, 'koKR', 'Znów dobrze się $gspisałeś:spisałaś;, $N. Dawno nie widziałem $gmłodego czarnoksiężnika:młodej czarnoksiężniczki; z takim potencjałem jak ty. Bądź $gpewny:pewna;, że nadal będę śledził twoje postępy i przygotuję cię do przyszłych prób oraz pomogę ci w nich.$B$BA teraz pokażę ci zaklęcie przywołania twojego świeżo ujarzmionego sukkuba.', 0),
(1476, 'koKR', 'Serce dobrego człowieka wygląda w sumie jak każde inne, kiedy widzi się je w ten sposób, nie sądzisz?$B$BByć może mamy na ten temat nieco... odmienne zdanie. Ale te wystarczą. Nie wątpię, że ich czystość zwabi sukkuba.', 0),
(1657, 'koKR', 'Ach, świetna robota! Oby Przymierze zadławiło się cuchnącym podarkiem, który mu daliśmy, tak jak my musieliśmy się dławić jarzmem niewoli u Plagi!$B$B$GDochowałeś:Dochowałaś; wierności ideałom Zaduszników, $N, i za to cię pozdrawiam. W ramach dodatkowej nagrody podzielę się z tobą smakołykami, które mam na Zaduszniki. Myślę, że okażą się całkiem przyjemną rozrywką!', 0),
(1801, 'koKR', 'Mapy! Obrazki, przybliżenia rzeczywistości. Nic mi po nich.$b$bW książkach, w opowieści, w opisie! Tam leży prawda. Oddałbym wszystkie mapy z tego sklepu za jedną książkę o narodzinach nekromancji albo opowieść o triumfie Mrocznej Pani.', 0),
(1803, 'koKR', 'No, no, no! Co my tu mamy?$B$BImponujące, $N. Nie sądziłem, że to możliwe, a jednak trzymam ją w rękach: kompletną Księgę Sprzysiężenia.$B$BPozwól, że przez chwilę ją przekartkuję, zanim znów ruszysz w drogę.', 0),
(1841, 'koKR', 'Przychodzisz po nagolenniki? Świetnie!$b$bEee... to ja robię zbroję dla ciebie czy ty dla mnie?$b$bTo był żart. Śmieszny? Nie potrafię ocenić... Straciłam poczucie humoru w tym samym czasie co węch. Mniej więcej wtedy, kiedy przestałam oddychać.', 0),
(1846, 'koKR', 'Dobra robota! Wszystkie wyglądają na mocne. Myślę, że świetnie się nadadzą. Jak orkowie znieśli to, że zabierasz im piszczele, $N? Bardzo się skarżyli?$B$BTo był kolejny żart. Nie śmiejesz się.$B$BNie jestem ostatnio zbyt zabawna, co...', 0),
(1847, 'koKR', 'Oto twoje nagolenniki, $N. Daj znać, jak leżą i czy trzeba coś poprawić. Staram się dogodzić klientom! A przynajmniej kiedyś się starałam.$B$BTeraz niespecjalnie dbam o swoje rzemiosło. Ale to i tak lepsze niż być bezmyślnym sługą Plagi!$B$BChyba.', 0),
(1882, 'koKR', 'Ach, to piękny okaz. Wyślę go naszym aptekarzom do zbadania, by ustalili, jak daleko sięga skażenie z Plagowisk.$B$BDobra robota, $N. W zamian za twoje usługi daję ci wybór: kula albo kostur. Którąkolwiek rzecz wybierzesz, okaże się bardzo przydatna.', 0),
(1886, 'koKR', 'Dobra robota, $N. $GPrzeszedłeś:Przeszłaś; pierwszą część próby. Miejmy nadzieję, że Andron niczego nie zwęszył i zdołamy go przekonać, że to ty jesteś posłańcem, na którego czeka.', 0),
(1898, 'koKR', 'Ach, tak, spodziewałem się ciebie. Nie wątpię, że nasi wspólni znajomi są zadowoleni z informacji, które im dotąd przekazałem?$B$BCóż, chyba nie ma sensu cię o to pytać; wątpię, by obarczali cię tą wiedzą. Po co tak ufać posłańcowi, hm?', 0),
(1899, 'koKR', 'No proszę, to z pewnością więcej informacji, niż spodziewałem się wyciągnąć z Androna. Daj mi chwilę, żebym to przejrzał, zanim zlecę ci kolejne zadanie.', 0),
(1960, 'koKR', 'Bardzo dobrze, $N. Istoty zamknięte w tych szkatułach zbadają nasze najtęższe umysły i ustalimy, co sprowadziło je do Podmiasta.$B$BJeśli ich pojawienie się to skutek wyrwy w naturalnym przepływie magii, musimy ustalić, czy wyrwa była przypadkowa. Jeśli nie była – jeśli to atak jakiejś magicznej siły – musimy się przygotować na kolejne, poważniejsze zakłócenia.', 0),
(1961, 'koKR', 'To bardzo dobry materiał. Nie mam wprawdzie talentu, by ocenić jakość tych klejnotów many, ale wkrótce się przekonamy, czy mają dość mocy, by uszyć z nich szaty ognia zaklęć...', 0),
(1962, 'koKR', 'Oto twoje szaty, $N. Noś je z godnością.', 0),
(1978, 'koKR', 'Hmm, to ciekawe. Tropiciele śmierci spisali się znakomicie, wywęszając tę sprawę.$B$BJak rozumiem, i tobie należy się pochwała za twoją postawę. Mam nadzieję, że wejdzie ci to w nawyk, $N. Moi tropiciele śmierci zawsze znajdą zajęcie dla kogoś takiego jak ty.', 0),
(1998, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N. Przyszło mi do głowy, że $gwyświadczyłeś:wyświadczyłaś; tropicielom śmierci wiele przysług i $gdowiodłeś:dowiodłaś; swojej wartości. Być może nadszedł czas, by poszerzyć twoją wiedzę o sztukach cienia.', 0),
(1999, 'koKR', 'Bardzo dobrze, $N! $GOpanowałeś:Opanowałaś; subtelną sztukę otwierania zamków, i to szybciej, niż mogłem się spodziewać.$B$BWidzę, że słusznie ci zaufałem. Wierz mi, $gchłopcze:dziewczyno;, przewiduję, że w tym fachu zajdziesz daleko.', 0),
(2342, 'koKR', 'Nareszcie – miotła godna Garretta. Jesteś $gwart:warta; każdego srebrnika, jaki na ciebie wydałem, tak mówię!$B$BSłyszycie mnie, plugawe nietoperze? Oto dzierżę ulubioną broń rodu Garrettów! Drżyjcie, nietoperze, drżyjcie!!', 0),
(2782, 'koKR', 'Ta tablica... Dość niezwykła... Gdzie ją $gznalazłeś:znalazłaś;, $N?', 0),
(2938, 'koKR', 'Ach, bardzo dobrze. Lydon wspominał, że trucizna w tej paczce jest najsilniejsza, z jaką miał do czynienia, i pracuje już nad jej nowymi zastosowaniami.$b$bPrzy odrobinie szczęścia znajdziemy ich wiele.$b$bDziękuję, $N. Twoje zasługi dla Królewskich Zakładów Chemicznych są niezaprzeczalne.', 0),
(2995, 'koKR', 'Doskonale, $N. Kiedy elfy z Wysokiej Doliny będą się trudzić, by odzyskać utracone informacje, my odetniemy te linie jeszcze skuteczniej...', 0),
(3341, 'koKR', 'Lojalność lisza jest niezachwiana, $N. Niech się przekonają, że taka lojalność przyniesie im tylko zagładę.', 0),
(3542, 'koKR', 'Masz, weź trochę grosza... kup se... <hik>... jakiś nowy pancerz czy coś...$b$bTo przyniesie parę błyszczących złociszy... odpowiednim... <hik> ludziom.', 0),
(3564, 'koKR', 'Doskonale... chwileczkę.$b$bHaha! Coś ty mu $gpowiedział:powiedziała;, jak $goddawałeś:oddawałaś; tablicę, $N? Przepłacił nam grubo za dużo! Nie żebym narzekała. $GPowiedziałeś:Powiedziałaś; mu, że umowa się zmieniła? A może znowu był pijany?$b$bNieważne... masz, weź jeszcze dodatkową działkę.', 0),
(3568, 'koKR', 'Cudownie. $GWróciłeś:Wróciłaś;, zanim umarła. Dobrze, dobrze.$B$BTo co, zabierzmy się do dzieła?$B$BObserwuję jej objawy od dłuższego czasu i wygląda to dość paskudnie. Dziwię się, że jeszcze stoi na nogach. Wymiotowała już trzy czy cztery razy, gdzie popadnie... przemiły zapach.$B$BDaj mi chwilkę, przygotuję coś do wypróbowania na naszej... przyjaciółce.', 0),
(3569, 'koKR', 'Chemik Cuely był bardzo usłużny... aż niepokojąco. Ale skoro mówi, że to mi pomoże, nie mam innego wyjścia. Nie mam czasu szukać innego rozwiązania. Rozmawiałam już z kapłanami i szamanami i żaden nie zdołał mi pomóc.$B$BMiejmy nadzieję, że Matka Ziemia czuwa nad moim duchem.', 0),
(3570, 'koKR', 'Nie sądziłem, że eliksir zadziała tak szybko. Dziękuję, $N. Zaraz zabiorę się do pracy nad resztą próbek. Jestem pewien, że już niedługo przydadzą się Lady Sylwanie i Porzuconym.', 0),
(3635, 'koKR', 'Przychodzisz uczyć się gnomiej inżynierii, co? No to $gtrafiłeś:trafiłaś; do właściwego gnoma. Rządząca frakcja Gnomoregan może i posługuje się polityką, by odsuwać tych, w których widzi intelektualne zagrożenie, ale wie, że wiedzy nie da się kontrolować.$B$BOni i ja dobrze wiemy, że kiedy odszedłem z Gnomoregan, stracili jednego z największych żyjących gnomich inżynierów. Jeśli okażesz się $gpojętnym uczniem:pojętną uczennicą;, nauczę cię tego, co umiem.', 0),
(3637, 'koKR', 'Przychodzisz uczyć się gnomiej inżynierii, co? No to $gtrafiłeś:trafiłaś; do właściwego gnoma. Rządząca frakcja Gnomoregan może i posługuje się polityką, by odsuwać tych, w których widzi intelektualne zagrożenie, ale wie, że wiedzy nie da się kontrolować.$B$BOni i ja dobrze wiemy, że kiedy odszedłem z Gnomoregan, stracili jednego z największych żyjących gnomich inżynierów. Jeśli okażesz się $gpojętnym uczniem:pojętną uczennicą;, nauczę cię tego, co umiem.', 0),
(4133, 'koKR', 'Dziękuję, że $gprzyszedłeś:przyszłaś;, $N. To miejsce nie jest pozbawione surowego uroku, ale brakuje mu wygód Aptekarium.$b$bDość uprzejmości. Przejdźmy do rzeczy, dobrze?', 0),
(4293, 'koKR', 'Ach, znakomicie. Te próbki świetnie się nadadzą. Dziękuję za pomoc.$B$BGdy zbierzemy wszystkie próbki szlamów, będziemy mogli ustalić więcej. Zaczynam podejrzewać, że przeczucie Lady Sylwany było nie tylko słuszne, ale i bardziej przenikliwe, niż nawet ona mogła przewidzieć. Te próbki są bardzo interesujące. Wystarczy zobaczyć, jak zareagowały z moimi związkami... hmm, tak, zdecydowanie trzeba to zbadać dokładniej.', 0),
(4294, 'koKR', 'Doprawdy zdumiewające, $N. Ten Krater Un\'Goro skrywa o wiele więcej sekretów, niż się spodziewałem. Ciekawe, co jeszcze odkryjemy w dalszych badaniach.$B$BPo prostu zdumiewające... spójrz na czystość tych próbek. Hmm, zastanawiam się, co to może znaczyć. Wydają się mieć naturę żywiołów, ale... jest w nich coś więcej. Przypominają mi... Przedwiecznych. Znajdowaliśmy ich ślady w całym Azeroth, a teraz zastanawiam się, czy te istoty nie są z nimi jakoś spokrewnione.$B$BTrzeba będzie zbadać to dokładniej.', 0),
(4642, 'koKR', 'Och, znakomicie, $N. Po prostu znakomicie.$B$BCóż za historia. Kto by pomyślał, że te dwa wejdą ze sobą w taką interakcję... Będę musiał poświęcić więcej czasu czynnikom środowiskowym, które wywołują zmiany w tych istotach.$B$BNa razie będę kontynuował badania. Może wkrótce znów porozmawiamy. Do tego czasu – powodzenia.', 0),
(4739, 'koKR', 'Ach, przysłał cię Kaal. Dobrze. A więc wieść dociera dość daleko, by trafić do przyszłych uczniów. To mnie cieszy.$B$BTo typowe dla nas, $N, że trzymamy się razem bez względu na rasę. To szczególnie ważne, bo ci, z którymi najczęściej mamy do czynienia, nie przebierają w złośliwości, jeśli nie zdołamy ich należycie ugłaskać lub kontrolować.$B$BCzuję, że wiele się $gnauczyłeś:nauczyłaś;, a jeśli zechcesz, pomogę ci stworzyć narzędzia, które uzupełnią twoje umiejętności.', 0),
(4769, 'koKR', 'To prawda. Wierzę, że w Iglicy Czarnej Góry przechowywana jest tablica zawierająca dawne receptury alchemiczne. Cieszę się, że tu jesteś, bo potrzebuję pomocy w jej odzyskaniu.$B$BRozgość się, a wyjaśnię ci resztę.', 0),
(4969, 'koKR', 'Ach, więc szukasz czegoś bardziej... namacalnego. W tym mogę ci pomóc, jeśli naprawdę jesteś $ggotów:gotowa;.$B$BMiło dla odmiany zobaczyć kogoś z nas, kto szuka większej mocy w innej postaci niż sama wiedza.$B$BCzy więc czujesz, że jesteś $ggotów:gotowa;, $N?', 0),
(5023, 'koKR', 'Paczka dla niejakiego Jeremiaha Felstone\'a, ostatni znany adres: Lordaeron... Powinienem móc ci pomóc.$b$bJeremiah Felstone mieszkał w mieście przed zarazą. A raczej powinienem powiedzieć: były Jeremiah Felstone – niektórzy Porzuceni zmienili nazwiska, by pozbyć się dawnego oblicza. Ten przypadek nie jest wyjątkiem: były Jeremiah Felstone nazywa się teraz Jeremiah Payson.$b$bChwileczkę... czy to nie ten handlarz karaluchami?', 0),
(5049, 'koKR', 'Od lat nie używałem tego nazwiska... ale owszem, kiedyś – przed tym wspaniałym nieżyciem – tak się nazywałem.$b$bTwierdzisz, że $gznałeś:znałaś; moją siostrę... a raczej, że niedawno z nią $grozmawiałeś:rozmawiałaś;.$b$bKtóra nie żyje.$b$bOd czterech lat.$b$bWiesz, gdyby moje kości nie były już wystarczająco kruche, kusiłoby mnie, żeby urwać sobie stopę na twoim siedzeniu. Niezła z ciebie hiena, co?$b$bCo... masz dla mnie paczkę od siostry?', 0),
(5961, 'koKR', 'Mroczna Pani z pewnością nie uważa, że jesteś $ggodzien:godna; spotkać jej czempiona. $GPrzyszedłeś:Przyszłaś; nakarmić moje ogary, tak? Nie może być innego powodu tego najścia.', 0),
(6144, 'koKR', 'Wielki krzyżowiec siedzi bezpiecznie w Szkarłatnym Bastionie, podczas gdy jego siły zalewają nasze ziemie, bezczeszczą nasze budowle i pomniki i mordują nasz lud.$B$BNadszedł czas, by rozprawić się z tym szkodnikiem. Staniesz się narzędziem naszej odpłaty.', 0),
(6145, 'koKR', '<Nathanos się śmieje.>$B$BZnakomicie! Nareszcie! Okazja, by zniszczyć Szkarłatną Wyrocznię!', 0),
(6322, 'koKR', 'Ta skrzynka musi dotrzeć do Grobowiska w Srebrzystym Borze? Nic prostszego – nasze nietoperze latają tam codziennie.', 0),
(6323, 'koKR', 'Rozkaz z Grobowiska? Niech będzie. To zaszczyt służyć tym, którzy służą naszej Mrocznej Pani.', 0),
(6324, 'koKR', 'Dobra robota, $N. Dzięki tej broni nasi strażnicy śmierci nie dadzą się zaskoczyć.$B$B$GOddałeś:Oddałaś; cenną przysługę naszej Mrocznej Pani.', 0),
(6628, 'koKR', 'Dobra robota, $N. Wątpiłem, czy $gprzestudiowałeś:przestudiowałaś; tekst, po który cię posłałem, ale odpowiedź jest prawidłowa.', 0),
(8273, 'koKR', 'No proszę, czyż to nie ciekawe? Mówisz, że $gznalazłeś:znalazłaś; tę tablicę na małej, bezludnej wyspie przy Urwiskach Widokowych w Zaziemiu, $N? Doprawdy bardzo ciekawe. <Oran ostrożnie odkłada tablicę i zaciera ręce.>$B$BDziękuję za twój trud w tej sprawie. Nasza Mroczna Pani będzie bardzo zadowolona z tego odkrycia. Proszę, pozwól, że odpowiednio cię wynagrodzę.', 0),
(8980, 'koKR', 'A więc miałem rację. Nie ma czasu do stracenia. Musimy ustalić źródło tych skażonych zapachów.$B$BProszę, to zwrot za wodę kolońską i perfumy.', 0),
(8982, 'koKR', 'Ach tak, perfumy i wodę kolońską dostałem całkiem niedawno. Nie wiem, jak długo jeszcze utrzymam je na półkach – wygląda na to, że wszyscy nie mogą się ich nachapać.$B$BJak dla mnie, nie widzę w nich nic nadzwyczajnego.', 0),
(8983, 'koKR', 'Niestety cały zapas perfum i wody kolońskiej sprzedałam Normanowi, karczmarzowi. Jeśli chcesz je kupić, porozmawiaj z nim – o ile coś mu jeszcze zostało.$B$BNie trać jednak czasu. Przekonasz się, że tej wodzie kolońskiej nie sposób się oprzeć.', 0),
(9177, 'koKR', '<Sylwana wyjmuje ci naszyjnik z dłoni.>$B$BTo niemożliwe! Po tylu latach... myślałam, że przepadł na zawsze.$B$B<Po dłuższej chwili Pani zdaje się na nowo dostrzegać otoczenie i odzyskuje panowanie nad sobą.>$B$BSądzisz, że to mnie rozbawi? Myślisz, że tęsknię za czasami, zanim zostałam królową Porzuconych? Tak jak ty, nic dla mnie nie znaczy, a Alleria Bieżywiatr to wspomnienie dawno martwe!$B$B<Upuszcza amulet na ziemię.>$B$BMożesz już zejść mi z oczu, $N.', 0),
(9180, 'koKR', '<Sylwana wyjmuje ci naszyjnik z dłoni.>$B$BTo niemożliwe! Po tylu latach... myślałam, że przepadł na zawsze.$B$B<Po dłuższej chwili Pani zdaje się na nowo dostrzegać otoczenie i odzyskuje panowanie nad sobą.>$B$BSądzisz, że to mnie rozbawi? Myślisz, że tęsknię za czasami, zanim zostałam królową Porzuconych? Tak jak ty, nic dla mnie nie znaczy, a Alleria Bieżywiatr to wspomnienie dawno martwe!$B$B<Upuszcza amulet na ziemię.>$B$BMożesz już zejść mi z oczu, $N.', 0),
(9189, 'koKR', 'Widzę tu, że ambasador Żal Słońca wiąże duże nadzieje z twoim dalszym awansem – przynosisz chlubę sin\'dorei. Szkoda tylko tej sprawy z Lady Sylwaną. Nie przejmuj się tym, $N, słusznie $gpostąpiłeś:postąpiłaś;, oddając jej naszyjnik. Powinna być wdzięczna, ale tacy już są władcy.$B$BSkoro tu jesteś i zechcesz pomagać Porzuconym w ich zadaniach, zachowuj się jak najlepiej. Nie chcesz chyba zaszkodzić naszej nowej więzi z Hordą, prawda?', 0),
(9310, 'koKR', 'Mówisz, że to pochodzi od truposza, który atakował miasto?$b$bDostaliśmy wieści o obozach pod nekropoliami, które przyzywa Plaga. Podejrzewam, że próbowali stworzyć taki w Podmieście. W przyszłości musimy zachować czujność.', 0),
(9425, 'koKR', 'No proszę! $GKolejny z moich braci przybywa:Kolejna z moich sióstr przybywa; z pomocą. Dobrze! Jest wiele do zrobienia, by wesprzeć naszych nowych przyjaciół Porzuconych, $N. Popytaj, komu możesz pomóc.$B$BWiem, że będziesz ich wspierać ze wszystkich sił!', 0),
(9621, 'koKR', 'A więc stało się. Podły zdrajca dostał to, na co zasłużył.$B$B$GDokonałeś tego sam:Dokonałaś tego sama;? Imponujący wyczyn, który dowodzi, że twoja rasa wciąż jest coś warta, $N.$B$BWidzę, że Lor\'themar ma kolejne wieści, które znacznie poprawią jego stosunki z Thrallem.', 0),
(9812, 'koKR', 'A więc stało się. Plugawy zdrajca dostał to, na co zasłużył.$b$b$gOddałeś:Oddałaś; wielkie usługi krwawym elfom i Hordzie. Dar\'khan był dla Thralla pretekstem, by nie przyjmować ich do naszego sojuszu. $gOczyściłeś:Oczyściłaś; drogę nowej Hordzie, $N.$b$bWidzę też, że Lor\'themar ma dodatkowe wieści, które znacznie poprawią jego stosunki z Thrallem. Znakomicie!', 0),
(10605, 'koKR', 'Ach, $gkolejny żądny mocy adept:kolejna żądna mocy adeptka;. Cudownie!$B$B$gMarny byłby z ciebie czarnoksiężnik:Marna byłaby z ciebie czarnoksiężniczka;, gdybyś nie $głaknął:łaknęła; mocy, prawda, $gchłopcze:dziewczyno;? Bierzmy się do roboty.', 0),
(12787, 'koKR', 'Ach, cóż za wspaniały z ciebie okaz. Choroba – choroby – tańczące w twoim wnętrzu muszą zsyłać ci wizje tak wzniosłe. Spędzimy razem długie noce na rozmowach, ty i ja, a ja będę wyłuskiwał z ciebie myśli, powoli wydobywając mięso z twojej czaszki.$b$bNie lękaj się, maleńki. Wiedza, którą zyskamy dzięki twojej ofierze, będzie niezwykła. Jesteś darem dla Porzuconych; zwiastujesz nową erę, w której ludy tego świata zaczną nas szanować. Twoje miejsce w naszej historii jest pewne...', 0),
(14036, 'koKR', 'Jeśli chcesz się nauczyć przyrządzania potraw na Dary Pielgrzymów, mogę ci pomóc. Jeśli jeszcze nie znasz się na gotowaniu, wystarczy trochę nauki i raz-dwa staniesz przy garach.', 0),
(14037, 'koKR', 'Pilnowanie, żeby na tych wszystkich stołach niczego nie zabrakło, to istna harówka. Jak się nad tym zastanowić, to dziwne, że zadajemy sobie tyle trudu, skoro nie musimy już jeść.$B$B<William wzrusza ramionami.>$B$BTradycja to tradycja.', 0),
(14058, 'koKR', 'Dzięki, $N. Teraz mogę pomóc gospodyni i dotrzymać słowa danego Robercie.', 0),
(14059, 'koKR', 'Dzięki za pomoc. Daj mi znać, jeśli kiedyś rozwikłasz zagadkę znikającego chutney.', 0),
(14349, 'koKR', 'Wielki krzyżowiec siedzi bezpiecznie w Szkarłatnym Bastionie, podczas gdy jego siły zalewają nasze ziemie, bezczeszczą nasze budowle i pomniki i mordują nasz lud.$B$BNadszedł czas, by rozprawić się z tym szkodnikiem. Staniesz się narzędziem naszej odpłaty.', 0),
(14350, 'koKR', '<Nathanos się śmieje.>$B$BZnakomicie! Nareszcie! Okazja, by zniszczyć Szkarłatną Wyrocznię!', 0),
(14351, 'koKR', 'A więc to ty $grozniosłeś:rozniosłaś; siły Przymierza w Międzygórzu? Słyszałem już twoje imię. Wieści szybko się rozchodzą.$B$BHordzie przyda się ktoś taki jak ty, jeśli tak dalej pójdzie, $N.$B$BMusimy mieć na oku wszystkie zagrożenia wokół nas, ale dopóki prowadzi ich ten król, ludzie nie przestaną sprawiać kłopotów. $GUdowodniłeś:Udowodniłaś;, że Horda ma dość siły, by w swoim czasie położyć temu kres.', 0),
(14352, 'koKR', 'Widziałem już ten znak na zwoju, kiedy służyłem w Północnej Grani. Mówisz, że był przy tej starej wiedźmie, która przewodzi świniom w Ciernisku Brzytwoskórych?$b$bNiech mnie szlag, jeśli pozwolę Pladze zdobyć tu przyczółek. Ten, kto to napisał – ten cały Malcin – jest najwyraźniej sługą Króla Lisza, a to czyni go celem. Twoim celem.$b$bKalimdoru nie dostaną.$b$b', 0),
(14353, 'koKR', 'Dobra robota, $N!$b$bHorda może być z ciebie dumna – nie $gpozwoliłeś:pozwoliłaś; Pladze zapuścić korzeni na naszej ziemi. Taki czyn zasługuje na nagrodę, a Porzuceni mają tyle rzeczy walających się po kątach, że na pewno kilka im nie zaszkodzi.$b$bMoże nie wiemy wszystkiego, co zrobili w Kurhanach, ale się dowiemy. Nie będą się wiecznie przemykać w ciemnościach.', 0),
(14355, 'koKR', 'Sylwana na pewno się ucieszy, że ten problem mamy z głowy, $N. Zadanie, które ci dałem, nie było łatwe, a jednak stoisz tu $gzwycięski:zwycięska;. To budzi szacunek, a to, czego $gdokonałeś:dokonałaś;, nie zostanie zapomniane.', 0),
(14356, 'koKR', 'Dobrze, $N. Dobra robota. Ukryję je przed wścibskimi oczami; ostatnie, czego nam trzeba, to odrodzona, potężna Rada Cieni.$B$BZaglądaj do mnie; najwyraźniej zawsze jest tu coś do zrobienia, a może mi się przydać kolejna para sprawnych rąk.', 0),
(14418, 'koKR', 'Hmm, to ciekawe. Tropiciele śmierci spisali się znakomicie, wywęszając tę sprawę.$B$BJak rozumiem, i tobie należy się pochwała za twoją postawę. Mam nadzieję, że wejdzie ci to w nawyk, $N. Moi tropiciele śmierci zawsze znajdą zajęcie dla kogoś takiego jak ty.', 0),
(14419, 'koKR', 'Ach, tak, spodziewałem się ciebie. Nie wątpię, że nasi wspólni znajomi są zadowoleni z informacji, które im dotąd przekazałem?$B$BCóż, chyba nie ma sensu cię o to pytać; wątpię, by obarczali cię tą wiedzą. Po co tak ufać posłańcowi, hm?', 0),
(14420, 'koKR', 'Dobra robota, $N. $GPrzeszedłeś:Przeszłaś; pierwszą część próby. Miejmy nadzieję, że Andron niczego nie zwęszył i zdołamy go przekonać, że to ty jesteś posłańcem, na którego czeka.', 0),
(14421, 'koKR', 'No proszę, to z pewnością więcej informacji, niż spodziewałem się wyciągnąć z Androna. Daj mi chwilę, żebym to przejrzał, zanim zlecę ci kolejne zadanie.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(232, 'koKR', 'Tak, w czym mogę pomóc? Przychodzisz w sprawach Królewskich Zakładów Chemicznych czy tylko po to, by rozjaśnić mi dzień?', 0),
(238, 'koKR', 'Tak, uważam, że Luca jest równie niepokojący jak ty. Nieważne. Daj mi zestaw do testów terenowych. Muszę go trochę przerobić, żeby mógł wykrywać właściwe surowce.$b$bMasz zestaw, prawda?', 0),
(357, 'koKR', '$N, $gzdobyłeś:zdobyłaś; księgę?', 0),
(444, 'koKR', 'Moje badania wymagają wielkiego skupienia. Mam więc nadzieję, że nie przychodzisz z błahostką.', 0),
(446, 'koKR', 'Witaj, $N. Co miał do powiedzenia Bethor?', 0),
(447, 'koKR', 'Witaj, $N. Jaką sprawę masz do Królewskich Zakładów Chemicznych?', 0),
(450, 'koKR', 'Widzę, że $gwróciłeś:wróciłaś;, $N.', 0),
(451, 'koKR', 'Co cię sprowadza z powrotem do Podmiasta, $N?', 0),
(491, 'koKR', '$N. $GPokonałeś:Pokonałaś; Thule\'a Kruczego Szpona?', 0),
(513, 'koKR', 'Nie widzisz, że jestem zajęty, $N? Mroczna Pani nalega na nową zarazę, zanim natarcie Plagi z Północnej Grani nas przytłoczy. A że od południa napierają ludzie, czas staje się moim najcenniejszym dobrem. Lepiej, żeby to było coś ważnego!', 0),
(515, 'koKR', 'Jak dobrze, że $gwróciłeś:wróciłaś;, $N. Tak strasznie się tu nudziłem. Żadnej rozrywki, poza truciem i zarażaniem Umpi, a potem jej ożywianiem... i tak w kółko, w kółko, w kółko.$b$bJak minęła podróż do Podmiasta? Czy los ci sprzyjał i $gzarżnąłeś:zarżnęłaś; po drodze jakichś ludzi?', 0),
(521, 'koKR', 'Tak? Masz coś do zameldowania?', 0),
(530, 'koKR', 'Masz te dłonie, $N?', 0),
(728, 'koKR', 'Ach, widzę, że mamy tu kogoś $gżądnego:żądną; wiedzy. Przychodzisz uczyć się z mojej kolekcji? Dobrze!$B$BAle strzeż się: tak jak wiedza daje siłę silnym... tak słabych doprowadza do szaleństwa.', 0),
(736, 'koKR', 'Jak idzie twoja misja, $N?', 0),
(864, 'koKR', 'Witaj z powrotem. A przynajmniej witaj, jeśli $gwróciłeś:wróciłaś; z zapieczętowanym zestawem do testów. W przeciwnym razie udam, że nie dostrzegam twojej kompletnej nieudolności, i oszczędzę ci mojego gniewu, dopóki nie zrobisz tego, co ci zlecono.', 0),
(1013, 'koKR', '$GZnalazłeś:Znalazłaś; księgę, $N?', 0),
(1109, 'koKR', 'Ach, widzę, że $gwróciłeś:wróciłaś;. Udało ci się zdobyć Guano z Cierniska?', 0),
(1113, 'koKR', '$GWróciłeś:Wróciłaś; ze Szkarłatnego Klasztoru? Do tego rozkosznego eksperymentu będę potrzebował wielu serc!$b$bVarimathras i Mroczna Pani z pewnością też się ucieszą, że pozbywamy się tych szkarłatnych szumowin...', 0),
(1160, 'koKR', 'Mam nadzieję, że Szkarłatna Krucjata trochę się nacierpiała, zanim $gwykradłeś:wykradłaś; im tę księgę.$b$bMoje zdanie o nich nie jest bezpodstawne. Krucjata mogła kiedyś podążać za Światłem, ale teraz chce zniszczyć każde stworzenie, które nie opowiedziało się po stronie jej wiary. Wierzą, że wszyscy nieumarli, Porzuceni czy nie, muszą zostać oczyszczeni, a ci, którzy podróżują po ich ziemiach, są albo szaleni, albo ulegli potężnej magii nieumarłych. Idioci. Idioci i głupcy, wszyscy co do jednego.', 0),
(1164, 'koKR', 'Zabij ich wszystkich i przynieś mi ich głowy!', 0),
(1471, 'koKR', 'Spodziewam się usłyszeć o twoim sukcesie, $N. Jeśli jednak zawiedziesz, niespełnienie moich oczekiwań będzie najmniejszym z twoich zmartwień.', 0),
(1473, 'koKR', 'To Egalin był moim nauczycielem. Niemal bez spojrzenia potrafił rozkazywać przywołanemu wędrowcowi Pustki.$B$BKiedy przyszła moja kolej, byłem zbyt pewny siebie. Nie igraj z mocami, którymi władasz, $N. Potrafią pochłonąć nawet najczujniejszych.', 0),
(1474, 'koKR', 'Spośród mocy zza pustki sukkub należy do najgroźniejszych, bo słabych najłatwiej owija sobie wokół palca.$B$BPamiętaj o tym teraz i w przyszłości.', 0),
(1476, 'koKR', 'Tempo twoich dotychczasowych postępów mile mnie zaskoczyło, $N. Przynieś mi serca, a znów zrobisz na mnie wrażenie.', 0),
(1657, 'koKR', 'Czy mieszkańcy Południowego Brzegu dostali już nasz „podarek”?$B$B<Przywoływaczka mroku Yanka śmieje się złowieszczo.>', 0),
(1803, 'koKR', 'Być może gonisz za bajkami, $N, ale nawet w najdzikszych plotkach tkwi ziarno prawdy.', 0),
(1805, 'koKR', 'Tak, $N? W czym mogę ci służyć?', 0),
(1846, 'koKR', 'Czekam na te piszczele, $N. Będą z nich ładne stelaże do twoich nagolenników.', 0),
(1882, 'koKR', 'Masz lwie paszcze? Ta odmiana kwiatów jest bardzo wrażliwa na energie magiczne, a zbadanie lwich paszczy rosnących tak blisko Plagowisk pozwoli nam ustalić, czy zaraza dotarła na Polany Tirisfal.', 0),
(1886, 'koKR', 'Masz dobre wieści?', 0),
(1898, 'koKR', 'Witaj. Mogę coś dla ciebie zrobić?', 0),
(1899, 'koKR', 'Udało się, $N?', 0),
(1960, 'koKR', '$GZbadałeś:Zbadałaś; to zakłócenie, $N? $GSchwytałeś:Schwytałaś; te istoty?', 0),
(1961, 'koKR', 'Anastasia uprzedziła mnie, że przyjdziesz, i jestem gotów uszyć twoje szaty. Masz klejnoty i płótno?', 0),
(1998, 'koKR', 'Pokładam w tobie najwyższą ufność – ta przysługa dla lorda Varimathrasa musi się udać.', 0),
(1999, 'koKR', '$GZnalazłeś:Znalazłaś; dokumenty, $N?', 0),
(2342, 'koKR', 'Zamiatanie nie ma końca... te nietoperze bez ustanku drwią ze mnie i mojej miotły. Powiedz, proszę, że $godzyskałeś:odzyskałaś; skarb mojej rodziny! Zaoferowałem ci swoje srebro – czy to mało?!', 0),
(2782, 'koKR', 'No proszę, a cóż to takiego?', 0),
(2938, 'koKR', 'Uprzedzono mnie o twoim przybyciu, $N. Masz dla mnie paczkę?', 0),
(2995, 'koKR', 'Kluczem jest odizolowanie elfów z Wysokiej Doliny. $GZnalazłeś:Znalazłaś; stróżówkę?', 0),
(3341, 'koKR', 'To sprawa najwyższej wagi, $N. Musimy powstrzymać każdą próbę zasilenia szeregów Plagi.', 0),
(3542, 'koKR', 'No... ...a to niespodzianka! Poszukiwacz przygóóód... !$b$bCo mogę... dla ciebie zrobić... ?', 0),
(3564, 'koKR', '$GSpotkałeś:Spotkałaś; się już z Andronem? Rzadko wychodzi z Podmiasta, więc chyba nie będzie trudno go znaleźć.', 0),
(3568, 'koKR', 'Wiesz, do czego to zmierza, prawda, $N? Ona nie ma szans przeżyć... spójrz tylko na nią. Najlepsze, co może teraz zrobić, to pomóc nam znaleźć lekarstwo na zarazę. Woda, którą wypiła, może zawierać wskazówkę, jak to zrobić. I tak umrze – równie dobrze może przedtem zrobić coś szlachetnego dla naszego ludu. Nie zgodzisz się?', 0),
(3569, 'koKR', 'Przybyłam do Podmiasta, bo słyszałam, że tutejsi alchemicy długo i wytrwale szukają lekarstwa na własną chorobę. Podsunięto mi, że może zdołają pomóc i mnie.$B$BChoć czuję się tu wszystkim, tylko nie mile widziana, nie miałam wyboru – choroba, która mnie dopadła, rozdziera mnie od środka, a ich pomocy potrzebowałam natychmiast.', 0),
(3570, 'koKR', 'Wiesz, do czego to zmierza, prawda, $N? Ona nie ma szans przeżyć... spójrz tylko na nią. Najlepsze, co może teraz zrobić, to pomóc nam znaleźć lekarstwo na zarazę. Woda, którą wypiła, może zawierać wskazówkę, jak to zrobić. I tak umrze – równie dobrze może przedtem zrobić coś szlachetnego dla naszego ludu. Nie zgodzisz się?', 0),
(3635, 'koKR', 'Witaj! Jeśli przychodzisz w sprawie robota samonaprowadzającego, który mógł przebić się przez ścianę twojego domostwa, to od razu odsyłam cię do mojego adwokata. W przeciwnym razie – co mogę dziś dla ciebie zrobić?', 0),
(3637, 'koKR', 'Witaj! Jeśli przychodzisz w sprawie robota samonaprowadzającego, który mógł przebić się przez ścianę twojego domostwa, to od razu odsyłam cię do mojego adwokata. W przeciwnym razie – co mogę dziś dla ciebie zrobić?', 0),
(4293, 'koKR', 'Do grupy kontrolnej potrzebuję co najmniej pięciu skażonych próbek, $N. Zbieraj dalej próbki szlamu ze Spaczonej Kniei, dopóki nie będziesz mieć tego, czego potrzebujemy. Tak nakazuje Lady Sylwana...', 0),
(4294, 'koKR', 'Tak, $N? Jak idą poszukiwania?', 0),
(4642, 'koKR', 'Jak idzie eksperyment, $N? Będę dalej badał próbki, które dla mnie $gzdobyłeś:zdobyłaś; – zaczynam rozumieć, dlaczego Lady Sylwana tak bardzo interesuje się tymi istotami. Jeśli naprawdę są cząstką Przedwiecznych, kto wie, jak możemy to obrócić na naszą korzyść.', 0),
(5023, 'koKR', 'Przychodzisz po pomoc do spisu ludności Podmiasta czy tylko zapytać, czy ktoś, kogo $gznałeś:znałaś;, nie żyje? Często mnie o to pytają.', 0),
(5049, 'koKR', 'Za każdym razem, gdy ktoś rozdepcze karalucha, płaczę. Proszę, nie doprowadzaj mnie do płaczu.', 0),
(5154, 'koKR', '$GZnalazłeś:Znalazłaś; księgę, $N?', 0),
(6145, 'koKR', 'Jeśli teraz ci się uda, prawie zasłużysz na mój szacunek.', 0),
(6322, 'koKR', 'Jeśli musisz pokonać daleką drogę, nietoperz to najlepszy wybór.', 0),
(6323, 'koKR', 'Dbam, by moja broń była w doskonałym stanie. Jest wyczyszczona i gotowa do użycia.', 0),
(6324, 'koKR', '$N, $gwróciłeś:wróciłaś;. Masz nasze zapasy z Podmiasta?', 0),
(6628, 'koKR', 'Jeśli chcesz przetrwać na tym świecie, musisz znać, moim zdaniem, tylko jedną zasadę: im więcej wiesz, tym więcej widzisz.$b$bJeśli będziesz się uczyć i obserwować, zaczniesz dostrzegać w świecie rzeczy, których nikt inny nie zobaczy.', 0),
(7819, 'koKR', 'Witaj ponownie, $N! Runicznej tkaniny potrzebujemy nieustannie i zawsze przyda nam się więcej, jeśli zechcesz się z nią rozstać. Za kolejną porcję dwudziestu sztuk runicznej tkaniny dopilnuję, by doceniono twoje nieustające starania na rzecz Podmiasta.$B$BGdy tylko zechcesz oddać porcję runicznej tkaniny, przyjmę ją.', 0),
(8840, 'koKR', 'Poszukiwaczom przygód, którzy mają tylko jeden sygnet pochwalny, wymieniam go na niewielkie uznanie Orgrimmaru.$B$BPamiętaj jednak, że lepiej oddać od razu komplet dziesięciu sygnetów; twoje starania zostaną wtedy docenione bardziej. Wymianę pojedynczych sygnetów prowadzimy z myślą o tych, którym brakuje do pełnej dziesiątki.$B$BSkoro to już wiesz, służę pomocą, jeśli nadal chcesz oddać jeden sygnet.', 0),
(8841, 'koKR', 'Przyjmuję sygnety pochwalne od poszukiwaczy przygód, którzy otrzymali je za służbę. Za każdy komplet dziesięciu, który mi przekażesz, dopilnuję, by twoje czyny zyskały znaczne uznanie Orgrimmaru. Przyjmuję też pojedyncze sygnety, ale uznanie za nie jest dużo mniejsze. Znacznie bardziej zależy nam na większych dowodach służby, choć żaden nie zostanie pominięty.$B$BSkoro to już wiesz, chętnie przyjmę twoje sygnety, jeśli chcesz oddać komplet.', 0),
(9180, 'koKR', 'A ty to kto?$B$BCo tam masz? Ten naszyjnik wygląda dziwnie znajomo. Daj go tutaj!', 0),
(9189, 'koKR', 'Witaj, $gbracie:siostro;. Jakie przynosisz wieści?', 0),
(9621, 'koKR', 'Ach, gość z Quel\'Thalas! Jakie wieści przynosisz?', 0),
(9812, 'koKR', 'Powiedziano mi, że przybędzie gość z Quel\'Thalas. Prawdę mówiąc, spodziewałam się krwawego elfa.$b$bJakie wieści przynosisz?', 0),
(14037, 'koKR', 'Na stołach naprawdę przydałoby się więcej tego farszu z chleba z przyprawami.', 0),
(14350, 'koKR', 'Jeśli teraz ci się uda, prawie zasłużysz na mój szacunek.', 0),
(14351, 'koKR', 'Czemu nie jesteś na polu bitwy, $N?', 0),
(14352, 'koKR', 'Czego chcesz, $N? Lepiej, żeby to było coś ważnego.', 0),
(14353, 'koKR', 'Podobno ten Malcin czeka przed Kurhanami Brzytwoskórych. Nie ma dyskusji – musi zginąć.$b$bMoi ludzie w Orgrimmarze donoszą, że ich zwiadowcy znaleźli tam ślady zarazy. Kolcozwierze też wyglądają na zarażone; są przez to znacznie silniejsze. Cokolwiek Plaga tam knuje, trzeba to zakończyć. Natychmiast.$b$bZnajdź tego Malcina i zabij go. Wróć tu, kiedy będzie martwy.', 0),
(14356, 'koKR', '$GZdobyłeś:Zdobyłaś; księgi? Nie mogą wpaść w niepowołane ręce.', 0),
(14419, 'koKR', 'Witaj. Mogę coś dla ciebie zrobić?', 0),
(14420, 'koKR', 'Masz dobre wieści?', 0),
(14421, 'koKR', 'Udało się, $N?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(2055, 0, 'koKR', 'Królewskie Zakłady Chemiczne odpowiedzą na wezwanie Mrocznej Pani, by odkryć Nową Zarazę i raz na zawsze wymieść ze świata Arthasa i jego bezbożną armię Plagi.', 0),
(2215, 0, 'koKR', 'Aby służyć Mrocznej Pani i Varimathrasowi, musimy przesunąć front naprzód i wytępić ludzkie robactwo.', 0),
(7407, 0, 'koKR', 'Nazywam się Zęzoświst i jestem głównym inżynierem Wodociągów Gadżetonu. W czym mogę pomóc?', 0),
(9078, 0, 'koKR', '$gMój drogi chłopcze:Moja droga dziewczyno;, przybywasz w samą porę, by wesprzeć Siły Ekspedycyjne Kargatu.\n', 0);
