INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(236, 'koKR', 'Badając rozmaite skamieniałe stworzenia, doszedłem do wniosku, że w zamierzchłych czasach wody Jeziora Lordamere nawiedziła wielka zaraza. Co ją wywołało? Może nigdy się nie dowiemy. Sądząc jednak po gęstych skupiskach szczątków rozsianych po dnie jeziora, zaraźliwość musiała być niezwykle wysoka. ', 0),
(237, 'koKR', 'Próbując odkryć przeszłość, zacząłem badać stworzenia współczesne w nadziei, że znajdę brakujący trop w tej zagadce. Jeziorne czatowniki i jeziorne pełzacze to prastare bestie zamieszkujące wyspy pośrodku Jeziora Lordamere. Porasta je mech przypominający ślady substancji na niektórych skamielinach. Muszę przeprowadzić dalsze badania, zanim odważę się snuć domysły, co oznacza ten związek. ', 0),
(238, 'koKR', 'Zbierając próbki mchu, natknąłem się na miejsce krwawej bitwy. Plemię murloków z Plugawopłetwych zostało oblężone przez grasującą bandę gnoli. Pole bitwy usiane było trupami zarówno gnoli, jak i murloków. Mijając zmasakrowane ciało murloka, zauważyłem dziwny stwardniały guz wystający z rany. Gdy zacząłem go badać, stało się jasne, że ma podobne właściwości jak zbierany przeze mnie mech. Niestety, poza tym jednym nie znalazłem żadnych innych guzów.', 0),
(376, 'koKR', 'Gwiazda Xil\'yeh\n  \nOstatnim znanym właścicielem tego klejnotu, który podobno pozwala posiadaczowi porozumiewać się z innymi światami, był ogr z Alterak, Grel\'borg Skąpiec. Według naszych źródeł Grel\'borg krąży po Ruinach Alterak w Górach Alterak i przetrząsa gruzy w poszukiwaniu kolejnych reliktów.', 0),
(377, 'koKR', 'Ręka Daguna\n  \nDagun to stwór z głębin, czczony przez murloki z Pyłowego Bagniska. Wywabiają go na powierzchnię specjalnym morskim wodorostem, zaczarowanym przez swoich szamanów. Poluj na murloki, zbierz ich zaczarowane wodorosty, a potem złóż je na ołtarzu murloków. Dagun przybędzie, a ty będziesz na niego czekać.\n\nChcę tę rękę.', 0),
(378, 'koKR', 'Serce dziedzictwa\n\nStare teksty mówią, że kto posiada Serce dziedzictwa, ten nie lęka się grobu. Być może to prawda, bo właściciel serca, troll Mogh, znany jest jako Mogh Nieumierający. Mogh, szaman z plemienia Rozłupywaczy Czaszek, mieszka w Dolinie Cierniodławów, w Ruinach Zul\'Mamwe.', 0),
(379, 'koKR', 'Przynieś mi te przedmioty – Gwiazdę, Rękę i Serce – a dam ci egzemplarz Kompendium Yagyin.\n\n– Strażnik', 0),
(669, 'koKR', 'Początki nieumarłych w Azeroth wcale nie sięgają zepsucia księcia Arthasa – zaczęły się na długo przed tym wydarzeniem. Wypadki, które doprowadziły do upadku Lordaeronu, zostały wprawione w ruch dużo wcześniej; wszystko zaczęło się od przybycia orczych klanów i Płonącego Legionu.', 0),
(670, 'koKR', 'Orkowie z Draenoru (świata, z którego pierwotnie pochodzili) byli szlachetnym ludem szamanów. Byli potężnymi wojownikami, silnymi ciałem i wolą. Właśnie dlatego wypatrzył ich Płonący Legion. Kil\'jaeden, jeden z najpotężniejszych demonów Legionu, zapragnął zniewolić orcze klany i uczynić z nich swoją armię przeciwko światom, których Płonący Legion jeszcze nie podbił.', 0),
(671, 'koKR', 'Kil\'jaeden przybył do przywódcy klanów, potężnego szamana imieniem Ner\'zhul. Obiecał mu niewyobrażalną magiczną moc i wiedzę, jeśli zawrze z demonem pakt, który uczyni klany niewolnikami Płonącego Legionu. Ten pakt przypieczętował nie tylko ich los, ale na zawsze także los ich świata.', 0),
(672, 'koKR', 'Z czasem Ner\'zhul pojął, jaki los czeka klany z rąk Płonącego Legionu, i orczy szaman zaczął się sprzeciwiać Kil\'jaedenowi. Rozgniewany demon zwrócił się do ucznia szamana, Gul\'dana, znacznie bardziej podatnego na zepsucie niż Ner\'zhul.', 0),
(673, 'koKR', 'To Gul\'dan odpowiadał za upadek szamanizmu w klanach. Obietnica mocy i władzy nad wrogami czyniła jego propozycje jeszcze bardziej kuszącymi. Z pomocą Kil\'jaedena Gul\'dan zaczął manipulować klanami. Orkowie, niegdyś szlachetni, stali się zepsutymi, bezmyślnymi dzikusami. Gdy w ich żyły wprowadzono demoniczną krew, stali się jeszcze bardziej bezwzględni i barbarzyńscy.', 0),
(674, 'koKR', 'Choć po porażce z Ner\'zhulem Kil\'jaeden zdołał zepsuć Gul\'dana, wciąż nienawidził dawnego szamana i poprzysiągł wyegzekwować ich pierwotny pakt. Pojmał Ner\'zhula i zaczął poddawać go niezwykle powolnym torturom cielesnym. Gdy Ner\'zhul błagał o śmierć, Kil\'jaeden przypominał mu, że ich pierwotny pakt wciąż obowiązuje. W końcu zabił orka, lecz tylko ciało. Ducha orczego szamana pochwycił, zanim ten zdążył odejść do Wypaczonej Otchłani.', 0),
(675, 'koKR', 'Kil\'jaeden zamknął ducha Ner\'zhula w bryle lodu pochodzącej z Wypaczonej Otchłani. Uwięzionego w lodzie ducha nasycił jeszcze większą mocą. Utrata ciała i wlanie tak niewyobrażalnej mocy wyznaczyły granicę przemiany Ner\'zhula.', 0),
(676, 'koKR', 'Kil\'jaeden cisnął bryłę lodu przez wymiary z powrotem do Azeroth, gdzie spadła na kontynent Północnej Grani, sprowadzając to wielkie zło na nasz świat. Ner\'zhul przepadł na zawsze; w jego miejsce powstał tron z lodu i nienawiści. Niegdyś szanowany przywódca szamanów stał się niewiarygodnie potężnym Królem Liszem.', 0),
(677, 'koKR', 'Ponieważ Kil\'jaeden nie ufał Królowi Liszowi, wysłał swoich upiornych władców, by strzegli ducha i pilnowali, żeby Król Lisz wykonywał jego rozkazy. Te wampiryczne sługi chętnie przybyły do Azeroth, zwabione zniszczeniem, mocą Króla Lisza i widmem zagłady wszystkich ras całej planety.', 0),
(678, 'koKR', 'Minęła ponad dekada. W tym czasie Król Lisz wykorzystał swoje ogromne moce, by przejąć władzę nad umysłami stworzeń Północnej Grani i kazać im wznieść wielką cytadelę nad jego mroźnym tronem. Gdy cała Północna Grań znalazła się pod jego panowaniem, Król Lisz wiedział, że musi zacząć przenikać do Lordaeronu. Uwięziony w lodzie dawny orczy szaman zaczął szukać kolejnych umysłów, którymi mógłby manipulować i sterować. Jego zew dotarł przez kontynenty.', 0),
(679, 'koKR', 'Wezwanie Króla Lisza nie przeszło niezauważone, zwłaszcza przez garstkę potężnych osób. Był wśród nich arcymag Kel\'Thuzad, wpływowy członek rady rządzącej Dalaranem – Kirin Toru. Jego pogoń za wszelkimi rodzajami magii łamała zakaz Kirin Toru dotyczący zgłębiania mrocznych sztuk. Kel\'Thuzad porzucił Kirin Tor i wszelkie więzy z utartym myśleniem, poprzysięgając nauczyć się od Króla Lisza wszystkiego, co tylko zdoła.', 0),
(680, 'koKR', 'Obaj zawarli pakt. Kel\'Thuzad miał otrzymać nieśmiertelność i ogromną moc w zamian za służbę Królowi Liszowi. Jego pierwszym zadaniem było wykorzystać swój majątek i wpływy w Lordaeronie, by założyć Kult Potępionych. Kult obiecywał wszystkim swoim członkom równość i życie wieczne, pod warunkiem że złożą przysięgę Ner\'zhulowi, bogu Kultu Potępionych.', 0),
(681, 'koKR', 'Następnie Ner\'zhul stworzył artefakty, które miały szerzyć zarazę wśród ludzkich społeczności Lordaeronu. Przekazał je Kel\'Thuzadowi i rozkazał czarodziejowi rozmieścić je po całej krainie. Wyznawcy Kultu mieli chronić artefakty za wszelką cenę.', 0),
(682, 'koKR', 'Gdy artefakty znalazły się na miejscu, zaraza zaczęła przesączać się w ziemię i dotykać nieświadomych mieszkańców. Na oczach Kel\'Thuzada armia Króla Lisza szybko rosła, a on sam wkrótce zapanował nad dużą częścią krainy. Armię tę nazwano Plagą, bo jej jedynym celem było wyplenić ludzkość z całego Azeroth.', 0),
(698, 'koKR', '\nKraina Azeroth kryje niezliczone cuda. Rośliny, zwierzęta, kultury i magia roją się na jej powierzchni. Zaiste, ciekawi świata znajdą tu nieskończoną różnorodność. Wystarczy tylko patrzeć.\n\nAle kto spojrzy dość głęboko, odnajdzie okna do zupełnie nowych światów, a każdy z nich kryje własne cuda.\n\nTak samo jak każdy kryje własne okropności. ', 0),
(699, 'koKR', '\nOto cel mojej księgi: skatalogować te istoty, te pozaświatowe bestie, które chciałyby zniszczyć nasze ziemie, aby odkrywcy, którzy się na nie natkną, wiedzieli, z czym mają do czynienia.\n\nJeśli więc uważasz się za strażnika Azeroth, czytaj dalej. I poznaj swojego wroga.\n\n– Ur\nMag z Dalaranu', 0),
(700, 'koKR', 'Bestią, o której piszę, jest worgen.\n\nDawne wiejskie podania mogą nawiązywać do tych stworzeń, bo które dziecko rolnika nie słyszało opowieści o bestialskich wilkołakach grasujących w lasach i na mokradłach za wsią?\n\nA w takich opowieściach może kryć się prawda – być może to przestrogi przed worgenami, przebrane za baśnie, które mają nas straszyć.', 0),
(701, 'koKR', 'Zanim jednak czytelnik zbędzie takie opowieści, pozwól, że cię zapewnię: worgeny istnieją. Być może nie pochodzą z naszego świata, lecz między ich domem a naszym istnieją przejścia, a potężna magia potrafi je tu sprowadzić.\n\nTakich inkantacji lepiej nie wypowiadać, bo gdziekolwiek stąpną worgeny, niosą ze sobą grozę i rozlew krwi.', 0),
(702, 'koKR', 'Worgena poznasz po podobieństwie do wilków z naszego świata. Patrząc na worgena, łatwo dostrzec, że szorstka sierść, spiczaste uszy i długi pysk upodabniają go do znanych nam wilków.\n\nRównie szybko zobaczysz jednak różnice: szorstka sierść okrywa potężne, dwunożne ciało, uzbrojone w długie kły i szpony jak sztylety. A za jego wyciem czai się złośliwość, jakiej nie ma w sobie żadna zwyczajna bestia.', 0),
(703, 'koKR', 'Dom worgenów to mroczne miejsce, miejsce koszmarów. Jeśli w tamtym świecie są zakątki bezpieczne przed przeklętymi worgenami, moje badania nie ujawniły żadnego takiego bastionu.\n\nA zważywszy na dzikość i niegodziwość worgenów, najpewniej takie bastiony nie istnieją.\n\nPrzypuszcza się, że worgeny zadowalają się pozostaniem w swoim świecie, bo choć niektóre z nich władają potężną magią, nigdy nie próbowały z własnej woli dotrzeć do Azeroth.\n\nI za to możemy być wdzięczni losowi.', 0),
(704, 'koKR', 'Jak wspomniano wyżej, niektóre worgeny biegle władają sztukami tajemnymi, a ich magia to magia ciemności i zepsucia.\n\nKlątwy i nadprzyrodzone trucizny są powszechne, więc bądź ostrzeżony – kto staje przeciw magom worgenów, powinien uzbroić się w osłony przed cieniem.', 0),
(705, 'koKR', 'Mam nadzieję, że żaden czarodziej z Dalaranu nie będzie szukał worgenów, nawet w dobrej wierze. Z tymi bestiami nie da się zawrzeć paktu, nie można poznać ich sekretów, nic dobrego z nich nie wyniknie.\n\nNajlepiej zostawić je w ich świecie. Bo jeśli znajdą się w naszym i nie zostaną zniszczone, grozi nam straszliwe niebezpieczeństwo...', 0),
(1731, 'koKR', 'Tu spoczywa król Terenas Menethil II – ostatni prawowity król Lordaeronu.$B$BWielkie były jego czyny – długie jego panowanie – niewyobrażalna jego śmierć. $B$B         „Niech Ojciec spoczywa bez winy za czyny syna. $B          Niech zakrwawiona korona pozostanie zaginiona i zapomniana”.$B', 0),
(2044, 'koKR', 'Na całym świecie znalazła się garstka potężnych osób, które usłyszały mentalne wezwanie Króla Lisza z Północnej Grani. Najwybitniejszą z nich był arcymag Dalaranu Kel\'Thuzad, jeden ze starszych członków Kirin Toru, rady rządzącej Dalaranem. Od lat uchodził za odszczepieńca, bo upierał się przy zgłębianiu zakazanej sztuki nekromancji. ', 0),
(2045, 'koKR', 'Gnany pragnieniem poznania wszystkiego o świecie magii i jego mrocznych cudach, frustrował się tym, co uważał za przestarzałe i pozbawione wyobraźni zasady swoich towarzyszy. Gdy usłyszał potężne wezwanie z Północnej Grani, arcymag skierował całą swą niemałą wolę na porozumienie się z tajemniczym głosem. Przekonany, że Kirin Tor jest zbyt lękliwy, by sięgnąć po moc i wiedzę kryjące się w mrocznych sztukach, postanowił nauczyć się, czego tylko zdoła, od niezmiernie potężnego Króla Lisza.', 0),
(2046, 'koKR', 'Zostawiwszy majątek i prestiżową pozycję polityczną, Kel\'Thuzad porzucił drogę Kirin Toru i na zawsze opuścił Dalaran. Ponaglany przez natarczywy głos Króla Lisza w swoim umyśle, sprzedał rozległe posiadłości i ukrył swoje bogactwa. Przemierzywszy samotnie wiele mil lądem i morzem, dotarł wreszcie do skutych lodem wybrzeży Północnej Grani.', 0),
(2047, 'koKR', 'Zmierzając do Lodowej Korony, by zaoferować swoje usługi Królowi Liszowi, arcymag przeszedł przez spustoszone, zniszczone wojną ruiny Azjol-Nerub. Kel\'Thuzad na własne oczy ujrzał zasięg i bezwzględność mocy Ner\'zhula. Zaczął rozumieć, że sojusz z tajemniczym Królem Liszem może być zarówno mądry, jak i owocny.', 0),
(2048, 'koKR', 'Po długich miesiącach wędrówki przez surowe arktyczne pustkowia Kel\'Thuzad dotarł wreszcie do mrocznego lodowca Lodowej Korony. Śmiało podszedł do mrocznej cytadeli Ner\'zhula i ze zdumieniem patrzył, jak nieumarli strażnicy w milczeniu go przepuszczają, jakby był oczekiwany. ', 0),
(2049, 'koKR', 'Kel\'Thuzad zszedł głęboko w zimną ziemię i dotarł na samo dno lodowca. Tam, w bezkresnej jaskini lodu i cieni, padł na twarz przed Mroźnym Tronem i ofiarował swoją duszę mrocznemu władcy umarłych.', 0),
(2050, 'koKR', 'Król Lisz był zadowolony ze swojego najnowszego rekruta. Obiecał Kel\'Thuzadowi nieśmiertelność i wielką moc w zamian za lojalność i posłuszeństwo. Spragniony mrocznej wiedzy i mocy Kel\'Thuzad przyjął swoją pierwszą wielką misję: udać się do świata ludzi i założyć nową religię, która czciłaby Króla Lisza jako boga.', 0),
(2051, 'koKR', 'Aby pomóc arcymagowi w wykonaniu misji, Ner\'zhul pozostawił Kel\'Thuzadowi jego człowieczeństwo. Wiekowy, lecz wciąż charyzmatyczny czarodziej miał za pomocą swoich mocy iluzji i perswazji wprawić uciśnione, pozbawione praw masy Lordaeronu w stan zaufania i wiary. A gdy już przykuje ich uwagę, miał im ofiarować nową wizję tego, czym mogłoby być społeczeństwo – i nową postać, którą mogliby nazwać swoim królem.', 0),
(2052, 'koKR', 'Kel\'Thuzad powrócił do Lordaeronu w przebraniu i w ciągu trzech lat wykorzystał swój majątek i intelekt, by zgromadzić tajne bractwo podobnie myślących mężczyzn i kobiet. Bractwo, które nazwał Kultem Potępionych, obiecywało swoim akolitom równość społeczną i życie wieczne w Azeroth w zamian za służbę i posłuszeństwo Ner\'zhulowi. ', 0),
(2053, 'koKR', 'Mijały miesiące, a Kel\'Thuzad znajdował wielu chętnych do swojego nowego kultu wśród zmęczonych, przeciążonych pracą robotników Lordaeronu. Osiągnięcie celu przyszło mu zaskakująco łatwo: zamienić wiarę mieszkańców w Świętą Światłość w wiarę w mroczny cień Ner\'zhula. Gdy Kult Potępionych rósł w siłę i wpływy, Kel\'Thuzad dbał, by jego poczynania pozostały ukryte przed władzami Lordaeronu.', 0),
(2054, 'koKR', 'Dzięki sukcesowi Kel\'Thuzada w Lordaeronie Król Lisz poczynił ostatnie przygotowania do ataku na ludzką cywilizację. Zamknął energię zarazy w przenośnych artefaktach zwanych kotłami zarazy i rozkazał Kel\'Thuzadowi przetransportować je do Lordaeronu, gdzie miały zostać ukryte w różnych wioskach kontrolowanych przez kult. ', 0),
(2055, 'koKR', 'Kotły, strzeżone przez lojalnych kultystów, miały następnie działać jak generatory zarazy, która przesączałaby się na niczego niepodejrzewające pola uprawne i miasta północnego Lordaeronu.', 0),
(2056, 'koKR', 'Plan Króla Lisza zadziałał doskonale. Wiele północnych wiosek Lordaeronu zostało skażonych niemal natychmiast. Tak jak w Północnej Grani, mieszkańcy, którzy zapadli na zarazę, umierali i powstawali jako posłuszni niewolnicy Króla Lisza. ', 0),
(2057, 'koKR', 'Kultyści Kel\'Thuzada pragnęli umrzeć i powstać na nowo w służbie swojego mrocznego pana. Radowali się na myśl o nieśmiertelności w nieżyciu. W miarę jak zaraza się szerzyła, na północnych ziemiach powstawało coraz więcej zdziczałych zombie. Kel\'Thuzad spojrzał na rosnącą armię Króla Lisza i nazwał ją Plagą, bo wkrótce miała pomaszerować na bramy Lordaeronu i wyplenić ludzkość z oblicza świata. ', 0),
(2063, 'koKR', 'Kultyści Kel\'Thuzada pragnęli umrzeć i powstać na nowo w służbie swojego mrocznego pana. Radowali się na myśl o nieśmiertelności w nieżyciu. W miarę jak zaraza się szerzyła, na północnych ziemiach powstawało coraz więcej zdziczałych zombie. Kel\'Thuzad spojrzał na rosnącą armię Króla Lisza i nazwał ją Plagą, bo wkrótce miała pomaszerować na bramy Lordaeronu i wyplenić ludzkość z oblicza świata. ', 0),
(2515, 'koKR', 'Z rozkazu najwyższego egzekutora Hadreca poniżej wymieniono przedmioty niezbędne do utrzymania zapasów Grobowiska:\n\n12 długich mieczy\n9 sztyletów\n8 okrągłych tarcz\n15 toporów\n1000 strzał\n\nRealizację tego zamówienia należy traktować jako bezpośredni rozkaz Mrocznej Pani, a odpowiedzialni za nią zostaną przedstawieni Jej uwadze, podobnie jak każdy, kto sprzeciwi się Jej woli lub w inny sposób będzie ją utrudniał.', 0),
(2926, 'koKR', '$B$BPS – Nasz wielki magister otrzymał z Rubieży odpowiedź w sprawie pytania Thralla. Odpowiedź brzmi: z całą pewnością tak.', 0);
INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
(4763, 4, 'koKR', 'Moja odpowiedź to Nozdormu.', '');
