INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1589, 'koKR', 'Do następnego spotkania, dzielna duszo.', '', 0),
(1963, 'koKR', 'No dobra, żałosne worki kości. Pokażcie, co umiecie. Bijcie przeciwnika i nie przestawajcie, dopóki nie powiem.', '', 0),
(1964, 'koKR', 'Stać! To nazywacie walką, robaki? Żałosne! Włóżcie w to serce – i tak nie jest wam już do niczego potrzebne!', '', 0),
(1965, 'koKR', 'Widzicie się w ogóle? Żałośniejszej parodii machania mieczem w życiu nie widziałem!', '', 0),
(1966, 'koKR', 'Już nie walczycie dla siebie, robaki! Teraz walczycie dla Królowej, więc pokażcie mi coś godnego jej uwagi!', '', 0),
(1967, 'koKR', 'Jesteście martwi, nie pogrzebani. A teraz pokażcie, na co was stać!', '', 0),
(1968, 'koKR', 'Te kupy drewna i słomy może okażą wam litość, ale Król Lisz nie okaże!', '', 0),
(1969, 'koKR', 'Żałosne worki robaczywego mięsa, stać was na więcej. No to udowodnijcie!', '', 0),
(1970, 'koKR', 'Miecz to nie narzędzie, to przedłużenie waszego ciała. Oczekuję więcej!', '', 0),
(1971, 'koKR', 'Co to ma być? Jeśli to jest walka, to ja jestem samym Lotharem!', '', 0),
(1977, 'koKR', 'Lysto, sprowadź jeńców.', '', 0),
(1978, 'koKR', 'Edwardzie. Tylerze. Przygotujcie się do pierwszej próby.', '', 0),
(1980, 'koKR', 'Jak widać, żadna to była próba. Zobaczmy, jak poradzicie sobie z drugą. Lysto, przyprowadź sługi Króla Lisza.', '', 0),
(1984, 'koKR', 'Czas stawić czoła ostatniej próbie, młodzi wojownicy! Szykujcie się do najcięższej walki, jaka was dotąd czekała.', '', 0),
(1985, 'koKR', 'Dobra robota, Edwardzie i Tylerze. Całkiem ładnie postępujecie w szkoleniu. Wkrótce znów wystawimy was na próbę.', '', 0),
(1988, 'koKR', 'To jest Dalin Kuźnomistrz. Uciekł z Lordaeronu, gdy uderzyła zaraza, i zabrał ze sobą ukochaną.', '', 0),
(1989, 'koKR', 'A to Comar Villard. Dwa tygodnie po ślubie ktoś uprowadził mu żonę z bezpiecznej Przystani Menethilów.', '', 0),
(1990, 'koKR', 'Głupcy.', '', 0),
(1992, 'koKR', 'Gdy natknął się na uchodźców przy Murze Szarogrzywych, uznał, że jego obowiązkiem jest ich wspomóc, a swoją kobietę wysłał dalej, do Międzygórza.', '', 0),
(1993, 'koKR', 'Dwakroć pięć lat minęło, a on wciąż jej szuka, choć pięknością nie była, a wiele pań chętnie zajęłoby jej miejsce.', '', 0),
(1994, 'koKR', 'I co sądzicie o mojej nowej zabawce?', '', 0),
(1995, 'koKR', 'Thereso, zanieś to ojcu Lankesterowi.', '', 0),
(1997, 'koKR', '', 'Mój pan Abernathy przesyła ci to.', 0),
(1998, 'koKR', '', 'Tak, mój panie.', 0),
(1999, 'koKR', '', 'Mój panie. Od ojca Lankestera.', 0),
(2000, 'koKR', 'Jak wam się podoba moja pupilka?', '', 0),
(2001, 'koKR', 'Czyż nie jest najwspanialszym małym dziełem?', '', 0),
(2002, 'koKR', 'Nie mówiłem, że moje nowe techniki dominacji zadziałają?', '', 0),
(2003, 'koKR', 'Tak dobra, jak zapowiadałem, prawda?', '', 0),
(2004, 'koKR', 'Poszło gładko, gdy tylko złamałem jej ducha.', '', 0),
(2005, 'koKR', 'Chyba nie liczycie, że zdradzę wam wszystkie swoje sekrety?', '', 0),
(2006, 'koKR', 'Odrobina rytualnych tortur potrafi zdziałać cuda.', '', 0),
(2007, 'koKR', 'Szczypta tortur, odrobina magii i solidna porcja inwazyjnej chirurgii. Oczywiście była przy tym przytomna.', '', 0),
(2008, 'koKR', 'Każdy ma jakąś słabość, trzeba ją tylko znaleźć.', '', 0),
(2009, 'koKR', 'Odkryłem, że usunięcie lub pobudzenie pewnych części mózgu czyni obiekt znacznie potulniejszym.', '', 0),
(2011, 'koKR', 'Ależ dziękuję, moja pupilko.', '', 0),
(2012, 'koKR', '', 'Doprawdy zdumiewające, Gerardzie. Jak tego dokonałeś?', 0),
(2013, 'koKR', '', 'Zdumiewające! Jak udało ci się trwałe zdominowanie?', 0),
(2014, 'koKR', '', 'Nie pochwalam twoich eksperymentów, Gerardzie, ale muszę przyznać, że wyniki robią wrażenie. Co właściwie jej zrobiłeś?', 0),
(2015, 'koKR', '', 'Niesłychane. Zdominowałeś ją, a mimo to zachowała świadomość i sprawność. Jak tego dokonałeś?', 0),
(2016, 'koKR', '', 'Zachowała wiedzę i mowę, a nawet samodzielność na tyle, by wykonywać dla ciebie zadania. Co dokładnie zrobiłeś?', 0),
(2017, 'koKR', '', 'Nigdy czegoś takiego nie widziałam. Żadnego skupienia ani utraty świadomości, gdy obiekt jest zdominowany. Co jej zrobiłeś?', 0),
(2018, 'koKR', '', 'Brawo, Gerardzie, znów przeszedłeś samego siebie.', 0),
(2019, 'koKR', '', 'Jestem naprawdę pod wrażeniem, Gerardzie. Myślałam, że tylko gadasz, ale widzę, że się myliłam.', 0),
(2020, 'koKR', '', 'Imponujące, bardzo imponujące. Umie jakieś sztuczki?', 0),
(2022, 'koKR', '', 'Bardzo ładnie, Gerardzie. Następnym krokiem będzie hodowla.', 0),
(2023, 'koKR', '', 'Zdumiewające odkrycie. Chętnie przyjrzałabym się wszystkim nieudanym eksperymentom.', 0),
(2024, 'koKR', '', 'Nie podoba mi się, że część problemów łatasz alchemią, ale wyniki popieram. Znakomita robota.', 0),
(2026, 'koKR', '', 'Twoja pupilka jest cudowna, Gerardzie, ale chyba przydałaby się jej obroża z dzwoneczkiem.', 0),
(2027, 'koKR', '', 'Musiałeś ją uczyć czystości, Gerardzie?', 0),
(2028, 'koKR', 'Fuj! Czemu ten łajdak przysyła mi swoje robactwo? Zejdź mi z oczu, zanim odbiorę ci resztkę życia. I zabierz to ze sobą.', '', 0),
(2029, 'koKR', '', 'Ach, tu jest.', 0),
(2030, 'koKR', '', '„Magiczne przepływy i ich wpływ na świat” Maginora Dumasa. Tej właśnie szukałam.', 0),
(2031, 'koKR', '', 'Naprawdę potrzebuję lepszego systemu układania tych ksiąg. Ach, to ta, której chciałam.', 0),
(2032, 'koKR', '', '„Mistyczny dziennik Khadgara, tom 8”. Chyba właśnie tego szukałam.', 0),
(2033, 'koKR', '', 'Ach, „Mistyczne przywołania arcymagów Dalaranu”. Doskonale.', 0),
(2034, 'koKR', '', 'Gdybym tylko znalazła „Magię i drogi mocy”. Ach, jest. Co ona tu robiła?', 0),
(2035, 'koKR', '', '„Magiczne maladie” – nie. „Magiczne macierze” – nie. Ach, jest: „Magiczne misteria”.', 0),
(2036, 'koKR', '', 'Oto mistyczna księga, której szukałam.', 0),
(2037, 'koKR', '', 'Tak, tak. Hmm, zdaje się, że odsyła do innej księgi. Chyba muszę znaleźć i tę.', 0),
(2038, 'koKR', '', 'Niewiele mi to dało. Sprawdzę tę drugą.', 0),
(2039, 'koKR', '', 'Właśnie to chciałam wiedzieć. Teraz muszę tylko znaleźć, gdzie omawiają wariancję strumienia.', 0),
(2040, 'koKR', '', 'Bardzo ciekawe. Ale jeśli tak jest, to moja teoria jest błędna. Muszę przeczytać ponownie pozostałe rozdziały i zobaczyć, co przeoczyłam.', 0),
(2041, 'koKR', '', 'A więc co do energii miałam rację. Zobaczmy, co na ten temat mówi druga księga.', 0),
(2042, 'koKR', '', 'Jeśli to się zgadza, czeka mnie jeszcze mnóstwo badań.', 0),
(2043, 'koKR', '', 'Ale to nie może być prawda. Gdzie ja położyłam tę drugą książkę?', 0),
(2049, 'koKR', '', 'Skoro tu jesteście, jesteście gotowi rozpocząć naukę przyzywania demonicznych sług, którzy będą spełniać wasze rozkazy. Zaczniemy od najpodlejszych istot, jakie zdołacie wezwać, i pójdziemy dalej. Zaczynajmy.', 0),
(2050, 'koKR', '', 'Najłatwiejszą do przyzwania istotą jest chochlik. Powinniście już umieć przywołać tego sługę, ale dla porządku zacznę właśnie od niego.', 0),
(2051, 'koKR', '', 'Ta plugawa mała bestia to chochlik. Jest mały i słaby, więc jako żywa tarcza na niewiele się zda, a zadawane przez niego obrażenia są w najlepszym razie przeciętne. Najlepiej sprawdza się jako wsparcie większej grupy.', 0),
(2052, 'koKR', '', 'Skoro mieliście okazję przyjrzeć się chochlikowi, przejdźmy do następnego sługi, którego zdołacie przyzwać – wędrowca Pustki.', 0),
(2053, 'koKR', '', 'Ta demoniczna istota to wędrowiec Pustki. Ma znaczną siłę i wytrzymałość, co czyni go idealnym obrońcą. Poślijcie go na wroga, a potem używajcie go jako tarczy, podczas gdy waszymi zaklęciami i umiejętnościami wysysacie z przeciwnika życie.', 0),
(2054, 'koKR', '', 'Jeśli nigdy go nie widzieliście, to widok wart uwagi. Istota budząca respekt zarówno na polu bitwy, jak i poza nim. A teraz przyjrzyjmy się temu, na co z pewnością czekali wszyscy moi uczniowie płci męskiej. Sukkub.', 0),
(2055, 'koKR', '', 'No dobrze. Pomijając oczywiste rozproszenie, jakie taka służka wywoła u waszych bardziej męskich wrogów, potrafi też zadawać imponujące obrażenia. Jednak jej wątła wytrzymałość sprawia, że jako tarcza jest niemal bezużyteczna.', 0),
(2056, 'koKR', '', 'Uczcie się pilnie, a może pewnego dnia sami przyzwiecie sukkuba, ale na razie czas przejść do łowcy spaczenia.', 0),
(2057, 'koKR', '', 'To, co widzicie przed sobą, to łowca spaczenia. Jego wrodzone zdolności obejmują magiczną blokadę i inne umiejętności, dzięki którym nie ma sobie równych w starciu z przeciwnikiem władającym magią.', 0),
(2058, 'koKR', '', 'W starciu z każdym rzucającym zaklęcia ta dzika bestia będzie waszym najlepszym przyjacielem. A teraz przyjrzyjmy się czemuś nieco innemu. Następna istota wesprze was w podróżach i znacznie ułatwi przyszłe wędrówki. Spójrzmy na rumaka spaczenia.', 0),
(2059, 'koKR', '', 'Wątpię, byście mieli wiele okazji zobaczyć takie stworzenie. Te demoniczne wierzchowce znacznie przyspieszą wasze podróże, służąc wam za wierzchowca, dopóki nad nimi panujecie. Trudno jednak je okiełznać, więc upewnijcie się, że jesteście gotowi, zanim spróbujecie.', 0),
(2060, 'koKR', '', 'No i proszę. Nasza lekcja przyzywania dobiegła końca. Wkrótce zacznie się nowe zajęcie, więc jeśli chcecie coś sobie odświeżyć, możecie zostać.', 0),
(2061, 'koKR', 'Hmm, wygląda na to, że Keever potrzebuje nowego obiektu. Jeśli ten głupiec Abernathy dalej będzie zabierał Keeverowi obiekty, Keever będzie musiał zamienić z nim słowo.', '', 0),
(2062, 'koKR', 'Ach, proszę bardzo. Teraz Keever musi wypróbować tę fiolkę i zobaczyć, czy działa.', '', 0),
(2063, 'koKR', 'Nie tego Keever się spodziewał. Keever chyba dodał za dużo korzeńca. Zobaczmy, czy drugie serum da to, czego Keever potrzebuje.', '', 0),
(2064, 'koKR', '%s szturcha małą ropuchę.', '', 0),
(2065, 'koKR', '%s poi ropuchę odrobiną dziwnego płynu.', '', 0),
(2066, 'koKR', '%s z wyraźnym rozczarowaniem szturcha małą, puchatą wiewiórkę.', '', 0),
(2067, 'koKR', 'No nie, tak to nie może być. Stworzenie jest o wiele za małe. Zobaczmy, co da trzecia partia Keevera.', '', 0),
(2068, 'koKR', '%s poi wiewiórkę odrobiną gęstego płynu.', '', 0),
(2069, 'koKR', '%s szturcha płochliwego królika.', '', 0),
(2070, 'koKR', 'Keever nie jest z tego zadowolony. Może gdyby Keever spróbował większej dawki, rozwiązałoby to ten kłopot.', '', 0),
(2071, 'koKR', '%s chwyta królika, wlewa mu płyn do gardła i wkłada go z powrotem do klatki.', '', 0),
(2072, 'koKR', 'Co to ma być? Czy Keever prosił o owcę? Keever chciał broni o wielkiej mocy, a dostał tylko tę owcę. Keever jest bardzo rozczarowany.', '', 0),
(2073, 'koKR', '%s raz po raz szturcha wełnistą owcę.', '', 0),
(2074, 'koKR', 'Keever jest wielce zadowolony.', '', 0),
(2075, 'koKR', '%s wlewa płyn do gardła wycieńczonemu mężczyźnie.', '', 0),
(2621, 'koKR', 'Mennet powiedział, że mam cię poprosić o komplet narzędzi złodziejskich.', 'Mennet powiedział, że mam cię poprosić o komplet narzędzi złodziejskich.', 0),
(2643, 'koKR', 'Potrzebuję kolejnego kompletu narzędzi złodziejskich.', 'Potrzebuję kolejnego kompletu narzędzi złodziejskich.', 0),
(2644, 'koKR', '', '%s zabiera się do pracy...', 0),
(2645, 'koKR', '', 'Skończyłam twoje nagolenniki, $n.', 0),
(2761, 'koKR', 'Chwileczkę, tylko to zszyję...', '', 0),
(2762, 'koKR', 'Proszę. Twoja szata jest gotowa, $n.', '', 0),
(2847, 'koKR', 'Niewierni! Trzeba ich oczyścić!', '', 0),
(3961, 'koKR', 'Chcesz zostać kowalem? Wykuwać ostrza, którymi wypatroszysz wroga? Młoty, którymi zmiażdżysz mu czaszkę? Ano, mogę pomóc, i to chętnie, jeśli poleje się z tego krew.', '', 0),
(4139, 'koKR', 'Witaj w Rozmaitościach „Błękitny Księżyc”, $N. Jeśli masz jakieś pytania, daj znać.', '', 0),
(4522, 'koKR', 'Gotowe! Robota skończona.', '', 0),
(4533, 'koKR', '', 'Co... co się dzieje?', 0),
(4554, 'koKR', 'Witaj, $gchłopcze:dziewczyno;... nazywam się Oglethorpe i być może to mnie zawdzięczasz któreś z tych niesamowitych gnomich urządzeń, jakie posiadasz! Jeśli wybuchło, to nie byłem ja; ale jeśli dzięki niemu się $gwzbogaciłeś:wzbogaciłaś;, możemy pomówić o tantiemach!$B$BA, i jeśli pochodzisz z Gnomoregan, weź dwa kąty proste, złóż je razem i maszeruj – w tył zwrot. Nie mam ci nic do powiedzenia.', '', 0),
(4555, 'koKR', 'No proszę, czyż to nie $n! Miło cię znów widzieć; nie potrafię wyrazić, jak wdzięczny jestem za pomoc, jakiej dotąd $gudzieliłeś:udzieliłaś; mnie i moim wynalazkom.$B$BCo mogę dziś dla ciebie zrobić?', '', 0),
(4569, 'koKR', 'Intruzi! Atakować intruzów!', 'Intruzi! Atakować intruzów!', 0),
(5519, 'koKR', 'Mój brat i ja poświęciliśmy się Sylwanie. To ona była naszym światłem, gdy nastały najczarniejsze czasy. Dzień w dzień składamy siebie w ofierze, by nasz lud przezwyciężył los, który nas wybrał.$B$BNie pozostaniemy słabi. Weźmiemy to, co nam się należy. Oddamy dziesięciokrotnie ból, który nam zadano. I zrobimy to z uśmiechem na twarzach.', '', 0),
(5520, 'koKR', 'Lady Sylwana poleciła zbadać niektóre zjawiska naturalne Azeroth. Uważa, że z sekretnej przeszłości tego świata można się wiele nauczyć.$B$BNie wiem, skąd o tym wie, ale ufam jej bez reszty, więc zrobię, co w mojej mocy.$B$BObecnie badam szlamy, mazie i tym podobne. Wszystkie te stworzenia mają zdaje się podobną budowę, ale środowisko silnie na nie wpływa.$B$BPrzydałaby mi się twoja pomoc w zbieraniu próbek tych stworzeń.', '', 0),
(5752, 'koKR', 'Mam nadzieję, że pewnego dnia będę wykuwać broń i zbroje z kości moich wrogów.', '', 0),
(5884, 'koKR', 'My mieć hak do skórowania. My dostać go od Killian Hagey, co uczyć nas zdzierać skóra z ubitych. Ty mieć ładna skóra. Ty znaleźć go w wewnętrzny krąg Dzielnica Łotrów.', 'My mieć hak do skórowania. My dostać go od Killian Hagey, co uczyć nas zdzierać skóra z ubitych. Ty mieć ładna skóra. Ty znaleźć go w wewnętrzny krąg Dzielnica Łotrów.', 0),
(6069, 'koKR', 'Jestem urzędnikiem miejskim, odpowiadam za spis ludności Podmiasta. Odkąd wyzwoliliśmy się spod Plagi, staramy się dokładnie śledzić liczbę mieszkańców naszego miasta. Dzięki tajemnym metodom i wyostrzonej dyscyplinie umysłu mam dostęp do tych rejestrów. Jeśli masz do mnie sprawę w tym zakresie, śmiało. W każdym razie $gpowinieneś:powinnaś; wiedzieć, czy masz.', '', 0),
(6194, 'koKR', 'Ach, nareszcie jakieś prawdziwe wyzwanie!', '', 0),
(6195, 'koKR', 'Światłości, daj mi siłę!', '', 0),
(6196, 'koKR', 'To wszystko?', '', 0),
(6197, 'koKR', 'Niegodni.', '', 0),
(6198, 'koKR', '', 'Światłość przemówiła!', 0),
(6532, 'koKR', '', 'Powstań, mój czempionie!', 0),
(6534, 'koKR', 'Ostrza światła!', '', 0),
(7215, 'koKR', 'Witaj, $n.', '', 0),
(7710, 'koKR', 'To prawda, byłem kiedyś człowiekiem. To, co mogłoby być wadą, działa na naszą korzyść, $n, bo ludzkie słabości znam od podszewki.', '', 0),
(7754, 'koKR', 'Skoro Algernon dba o moje zapasy, mogę tu pracować, nie szukając ani jednego zioła. Jeśli już nigdy nie będę musiał oglądać cudów natury, to i tak będzie za wcześnie.', '', 0),
(7764, 'koKR', 'Wraz z moimi kolegami gromadzimy najbardziej zabójcze znane nam substancje i sprawdzamy ich działanie na naszych wrogach. Gdy zdobędę wszystko, czego potrzebuję, uwarzę takie zarazy, jakich ten świat jeszcze nie widział.', '', 0),
(7823, 'koKR', 'Mroczna Pani powiedziała, że wiedza będzie naszą największą bronią w tej wojnie.', '', 0),
(7846, 'koKR', 'Nie mam czasu na próżne plotki, jestem profesjonalistą!', '', 0),
(7880, 'koKR', 'Nie mam czasu do stracenia, obcy. Mów, z czym przychodzisz, albo odejdź!', '', 0),
(7917, 'koKR', '', 'Rzadko miewam gości. Szukasz czegoś konkretnego, tak?', 0),
(7976, 'koKR', 'Kiedy wygrzebałem się z grobu, myślałem, że rodzina przyjmie mnie z otwartymi ramionami. Zamiast tego przegnali mnie z wioski, krzycząc w języku, którego już nie rozumiałem.', '', 0),
(8024, 'koKR', 'Przed śmiercią byłem bibliotekarzem; nie miałem nic wspólnego z wojnami i zarazami. Nigdy nie prosiłem, by stać się czymś takim. Z drugiej strony, skoro mój umysł znów należy do mnie, nie zamierzam się poddać bez walki.', '', 0),
(8080, 'koKR', 'Rzadko ktoś tu do nas zagląda. Może cię czymś zainteresuję?', '', 0),
(8094, 'koKR', 'Witaj. Nasze nietoperze są dobrze wyszkolone i nakarmione. Szybszych nie znajdziesz.', '', 0),
(8095, 'koKR', 'Czym mogę służyć?', '', 0),
(8096, 'koKR', 'Witaj. Nie za dobrze mi wychodzi uśmiechanie się, ale wierz mi, z radością ci usłużę.', '', 0),
(8176, 'koKR', '', 'Krawiectwo potrafi się bardzo przydać. Raz musiałam sobie przyszyć rękę z powrotem.', 0),
(8190, 'koKR', 'Płótno ujdzie. Osobiście wolę pracować z ludzką skórą.', '', 0),
(8306, 'koKR', 'Lysto, sprowadź nieumarłych jeńców.', '', 0),
(8307, 'koKR', 'Lysto, przyzwij... plugastwo!', '', 0),
(8373, 'koKR', 'Kel\'Thuzad? Jeśli w ogóle znasz to imię, to może faktycznie $gprzeczytałeś:przeczytałaś; księgę, po którą cię posłałem.$B$BNiestety, twoja odpowiedź jest błędna.', '', 0),
(8374, 'koKR', 'Gul\'dan. Niewielu w Azeroth słyszało to imię.$B$BNiestety, to nie jest poprawna odpowiedź.', '', 0),
(8375, 'koKR', 'Ciekawa odpowiedź na moje pytanie... i błędna.', '', 0),
(8376, 'koKR', 'Ach, Ner\'zhul. Tego imienia nie należy wymawiać lekkomyślnie, ale sam prosiłem cię o odpowiedź.$B$BA Ner\'zhul to odpowiedź poprawna.', '', 0),
(8377, 'koKR', 'Moja odpowiedź to Kel\'Thuzad.', 'Moja odpowiedź to Kel\'Thuzad.', 0),
(8378, 'koKR', 'Moja odpowiedź to Gul\'dan.', 'Moja odpowiedź to Gul\'dan.', 0),
(8379, 'koKR', 'Moja odpowiedź to Kil\'jaeden.', 'Moja odpowiedź to Kil\'jaeden.', 0),
(8380, 'koKR', 'Moja odpowiedź to Ner\'zhul.', 'Moja odpowiedź to Ner\'zhul.', 0),
(8381, 'koKR', 'Moja odpowiedź to Ysera.', 'Moja odpowiedź to Ysera.', 0),
(8382, 'koKR', 'Ach, Ysera Śniąca.', '', 0),
(8383, 'koKR', 'Moja odpowiedź to Neltharion.', 'Moja odpowiedź to Neltharion.', 0),
(8384, 'koKR', 'Moja odpowiedź to Alexstraza.', 'Moja odpowiedź to Alexstraza.', 0),
(8385, 'koKR', 'Moja odpowiedź to Malygos.', 'Moja odpowiedź to Malygos.', 0),
(8386, 'koKR', 'Neltharion, hmm? Odpowiedź nie gorsza od innych, prawda?', '', 0),
(8387, 'koKR', 'Alexstraza Życiodajna. Wspaniała istota.', '', 0),
(8388, 'koKR', 'Malygos, powiadasz?', '', 0),
(8389, 'koKR', 'Witaj, $N. Czy mogę ci w czymś pomóc?', '', 0),
(8390, 'koKR', 'Moje pytanie brzmi tak, $N:$BKtóry z Aspektów stworzonych przez tytanów stał się nikczemną istotą znaną jako Śmiercioskrzydły?', '', 0),
(8391, 'koKR', 'Zawsze miło, gdy ktoś chce ze mną porozmawiać. Jak ci się wiedzie, $N?', '', 0),
(8392, 'koKR', 'A teraz odpowiedz mi na to, $n:$BKtóra istota stała się Królem Liszem, zanim rozniosła zarazę po Lordaeronie?', '', 0),
(8393, 'koKR', 'To zła odpowiedź, $n. Precz stąd.', '', 0),
(8394, 'koKR', 'Obawiam się, że nie, $n. A teraz poczuj wstyd, który na siebie $gściągnąłeś:ściągnęłaś;.', '', 0),
(8419, 'koKR', 'Intruzi! Atakować intruzów!', 'Intruzi! Atakować intruzów!', 0),
(8704, 'koKR', 'Witaj w biurze rejestracji gildii Podmiasta. Czego chcesz?', '', 0),
(8873, 'koKR', 'Pewnie przychodzisz nauczyć się władać nową bronią? Streszczaj się, jestem bardzo zajęty!', '', 0),
(8874, 'koKR', 'Powiem ci, dokąd iść, jeśli powiesz mi, co cię interesuje.', '', 0),
(9893, 'koKR', 'Ty tam... w twoim najlepszym interesie jest wspierać Porzuconych w tych ciężkich czasach. Słuchaj uważnie, bo nie lubię się powtarzać.$B$BMamy obecnie dotkliwy niedobór tkanin. Bandaży i prostych materiałów zaczyna brakować, dlatego przyjmujemy datki, by uzupełnić kurczące się zapasy. Choć nie dostaniesz za to zapłaty – na tym właśnie polega datek – twoja pomoc nie przejdzie niezauważona.', '', 0),
(10523, 'koKR', 'Przybywasz, by walczyć za nas w Wąwozie Wojennej Pieśni? Lok\'tar Ogar, $N!', '', 0),
(10527, 'koKR', 'Straż Gromdardy musi zostać zniszczona! $GGotów:Gotowa; na Dolinę Alterak, $N?', '', 0),
(10536, 'koKR', 'Rozejrzyj się, $N. Bez wątpienia jesteś w doborowym towarzystwie, a mimo to sądzę, że musisz się jeszcze wykazać. Hmm, może pozwolę ci wesprzeć naszą sprawę w Kotlinie Aratorskiej. Co ty na to?', '', 0),
(10659, 'koKR', 'Popioły płonącego Wiklinowego Człowieka promieniują magiczną mocą.', '', 0),
(10660, 'koKR', 'Rozsmaruję popiół na twarzy jak barwy wojenne!', 'Rozsmaruję popiół na twarzy jak barwy wojenne!', 0),
(10661, 'koKR', 'Popioły płonącego Wiklinowego Człowieka promieniują magiczną mocą. Masz już popiół na twarzy.', '', 0),
(11488, 'koKR', 'Gdzie jest Nestor Grobowrodzony?', 'Gdzie jest Nestor Grobowrodzony?', 0),
(11490, 'koKR', 'Nestor Grobowrodzony przebywa w pobliżu Brill na Polanach Tirisfal.', 'Nestor Grobowrodzony przebywa w pobliżu Brill na Polanach Tirisfal.', 0),
(12131, 'koKR', 'Melduj się! Jakie ważne wieści przynosisz? Streszczaj się... Dama Złotonośna i ja jesteśmy w trakcie narady strategicznej.', '', 0),
(12157, 'koKR', 'Mogło pójść lepiej. $n, podejdź, proszę. Mam coś, czym musisz się dla mnie zająć.', '', 0),
(12161, 'koKR', 'Witaj. Jestem ambasador Żal Słońca z sin\'dorei, czyli krwawych elfów, jak nas powszechnie nazywają. Wiążę wielkie nadzieje z tym, że nowe przymierze między nami a Hordą okaże się korzystne dla obu stron.', '', 0),
(12167, 'koKR', 'Witaj. Jestem tu, by służyć radą najwyższemu egzekutorowi, który może z niej korzystać wedle uznania. Wierzę, że razem uczynimy Hordę silniejszą niż kiedykolwiek i raz na zawsze odeprzemy zagrożenie ze strony Plagi!', '', 0),
(12389, 'koKR', 'Pokłońcie się! Klęknijcie przed Spopielaczem! Nadchodzi nowy świt, bracia i siostry! Nasze przesłanie dotrze do szumowin tego świata przez wybrańca!', '', 0),
(12390, 'koKR', 'Dzierżysz miecz mojego ojca, $n. Moi żołnierze są twoi, $gmój panie:moja pani;. Weź ich... Prowadź ich... Nieczystych trzeba wytępić. Trzeba ich oczyścić z ich skazy.', '', 0),
(12470, 'koKR', 'Ojcze... Ale... Jak?', '', 0),
(12472, 'koKR', 'Wybacz mi, ojcze! Błagam...', '', 0),
(12529, 'koKR', 'Tak dobrze cię widzieć, $gbracie:siostro;! Od tego miejsca przechodzą mnie ciarki. Skoro już tu jesteś, koniecznie skorzystaj z wielu możliwości, jakie dają ci ci tak zwani Porzuceni.', '', 0),
(12553, 'koKR', 'Z całym szacunkiem, pani, nie walczyłaś z Plagą tak jak ja. Właśnie dlatego Pani wyznaczyła mnie, bym pomógł ci pokonać Dar\'khana, i dobrze byś zrobiła, rozważając moje słowa.', '', 0),
(12554, 'koKR', 'Stanowczo się nie zgadzam. Dar\'khan nie dostanie posiłków, bo utknie w wąskim gardle. Do Ostoi Śmierci prowadzi tylko jedna droga, w tę i z powrotem. Wasz zdrajca był głupcem, że sam się tam zapędził w kozi róg, a ja zamierzam wykorzystać tę słabość!', '', 0),
(12555, 'koKR', 'To wojna, damo Auriferous, a na każdej wojnie giną ludzie! Musimy zabezpieczyć tylko dwa ziguraty. Okopiemy się, a potem zdobędziemy Wieżę Potępionych i jej pana brutalną siłą. Wtedy dostaniesz swoje Quel\'Thalas.', '', 0),
(12556, 'koKR', 'Gdyby wasi Obieżyświaci byli tu, by nas wesprzeć, może bym się zgodził. Ale oni zamiast tego zajmują się trollami z plemienia Cienistej Sosny na waszej wschodniej granicy. Im dłużej na nich czekamy, tym silniejsza staje się Plaga.', '', 0),
(12558, 'koKR', 'Mam wrażenie, że argumentujesz za mną, ale owszem, przydałoby się więcej posiłków. Odpowiem jednak, że szybciej byłoby ściągnąć Obieżyświatów z ich bezsensownych potyczek z trollami.', '', 0),
(12559, 'koKR', 'Damo Auriferous, to my jesteśmy posiłkami. Może się zdarzyć, że Pani z czasem przyśle więcej żołnierzy. Lepiej przekonaj Srebrną Lunę, by zebrała wszystkie siły i oddała je tutaj do naszej dyspozycji.', '', 0),
(12560, 'koKR', 'Masz rację; musimy skupić się na Pladze. Zostawmy trolle i wioski, a całą uwagę skierujmy na Ostoję Śmierci! Gdy Dar\'khan padnie, przekonasz się, że reszta „ciała” Plagi szybko się rozpadnie, pozbawiona „głowy”.', '', 0),
(12561, 'koKR', 'Posiłki Porzuconych? Siły Podmiasta są rozciągnięte do granic, Plaga naciska ze wszystkich stron. Nie, tą sprawą zajmą się głównie krwawe elfy. My, Porzuceni, jesteśmy tu jako wsparcie i doradcy.', '', 0),
(12567, 'koKR', 'Znów stanowczo nie zgadzam się z twoją oceną sytuacji strategicznej. Twój plan zbytnio rozproszy nasze siły. Do szturmu na Ostoję Śmierci zostanie nam tylko niewielki oddział. Nie mogę z czystym sumieniem wykonać takiej strategii.', '', 0),
(12568, 'koKR', 'Rozproszone po Widmowych Ziemiach, nasze siły na niewiele się zdadzą przy szturmie na Ostoję Śmierci. Nie, pani, jestem tu, by zabić Dar\'khana, i to właśnie zamierzam zrobić!', '', 0),
(12569, 'koKR', 'Już to przerabialiśmy. Tylko skupiony szturm na Ostoję Śmierci może się powieść. Pozostałe cele to rozrywki, na które nie możemy sobie pozwolić. Radzę, byś przekazała swojemu kapitanowi Heliosowi, że ma przerwać kampanię przeciw trollom z plemienia Cienistej Sosny i skupić się wyłącznie na Pladze.', '', 0),
(12570, 'koKR', 'Może odłóżmy na razie tę sprawę, aż twój kucharz przygotuje ci posiłek? Jeśli pozwolisz, że to powiem, wyglądasz na nieco zmizerniałą. Wrócimy do dyskusji, gdy poczujesz się bardziej sobą.', '', 0),
(13228, 'koKR', 'Słyszałem co nieco o twoich wyczynach, $n. Wiem, że póki jesteś tu, na ziemiach Porzuconych, zachowasz się z godnością, jak $gprawdziwy bohater:prawdziwa bohaterka; sin\'dorei!', '', 0),
(13465, 'koKR', '', 'Pamiętaj tylko, $n, że w naszym najlepszym interesie jest, żebyś $gzrobił:zrobiła; jak najwięcej dla tych... tych ludzi.', 0),
(16167, 'koKR', 'Zimowa Uczta nie jest już taka jak dawniej, ale kiedy odprawiam te same rytuały co zawsze, wciąż coś czuję.', 'Zimowa Uczta nie jest już taka jak dawniej, ale kiedy odprawiam te same rytuały co zawsze, wciąż coś czuję.', 0),
(16195, 'koKR', 'Wciąż odprawiamy te same rytuały, ale Zimowa Uczta wydaje się teraz pusta. Prawdziwe świętowanie jest w Orgrimmarze.', 'Wciąż odprawiamy te same rytuały, ale Zimowa Uczta wydaje się teraz pusta. Prawdziwe świętowanie jest w Orgrimmarze.', 0),
(16197, 'koKR', 'Dla wielu Porzuconych księżyc zajął w sercach miejsce, które niegdyś należało do słońca. Jeśli jednak chcesz dołączyć do świętowania, udaj się do Gaju Luny w Kalimdorze. W sali tronowej nad Podmiastem znajdziesz druidów, którzy cię tam przeniosą.', 'Dla wielu Porzuconych księżyc zajął w sercach miejsce, które niegdyś należało do słońca. Jeśli jednak chcesz dołączyć do świętowania, udaj się do Gaju Luny w Kalimdorze. W sali tronowej nad Podmiastem znajdziesz druidów, którzy cię tam przeniosą.', 0),
(17963, 'koKR', 'Horda nie może pozwolić, by draenei i ich wścibskie Przymierze przejęli wszystkie ogniwa many na Rubieży. Dołączysz do krwawych elfów w szturmie na Oko Cyklonu?', 'Horda nie może pozwolić, by draenei i ich wścibskie Przymierze przejęli wszystkie ogniwa many na Rubieży. Dołączysz do krwawych elfów w szturmie na Oko Cyklonu?', 0),
(18023, 'koKR', '', 'Mograine poległ! Zapłacicie za tę zdradę! Powstań, mój czempionie! Powstań!', 0),
(18026, 'koKR', 'U twego boku, pani!', '', 0),
(19205, 'koKR', 'Co masz dla mnie, ambasadorze?', 'Co masz dla mnie, ambasadorze?', 0),
(19206, 'koKR', 'Tylko mały śpiewnik, który, jak sądziłem, chętnie przyjmiesz. Zawiera słowa pieśni zwanej Lamentem Wysoko Urodzonych – tej, którą lady Sylwana wyczarowała z samego powietrza.', '', 0),
(20122, 'koKR', 'Niegodni.', '', 0),
(20395, 'koKR', 'Spuścić psy!', '', 0),
(20617, 'koKR', 'Walki kosturem uczą Hanashi, trollowy mistrz broni w Dolinie Honoru w Orgrimmarze, oraz Ansekhwa, taureński mistrz broni, który szkoli na dolnym środkowym wzniesieniu Gromowych Urwisk.', 'Walki kosturem uczą Hanashi, trollowy mistrz broni w Dolinie Honoru w Orgrimmarze, oraz Ansekhwa, taureński mistrz broni, który szkoli na dolnym środkowym wzniesieniu Gromowych Urwisk.', 0),
(21668, 'koKR', 'Odczep się. Nie mam nic dla takich jak ty.', 'Odczep się. Nie mam nic dla takich jak ty.', 0),
(22184, 'koKR', 'Mój brat Krixx uważa, że ma ciężko, pracując w Orgrimmarze. Nic nie dorówna smrodowi tego miejsca. Przynajmniej szef miał tyle przyzwoitości, żeby dać mi dodatek za pracę w szkodliwych warunkach!\nCo? Chcesz zobaczyć, gdzie jest sterowiec? Dobrze się składa, mam tu swój lokalizator sterowców!', 'Mój brat Krixx uważa, że ma ciężko, pracując w Orgrimmarze. Nic nie dorówna smrodowi tego miejsca. Przynajmniej szef miał tyle przyzwoitości, żeby dać mi dodatek za pracę w szkodliwych warunkach!\nCo? Chcesz zobaczyć, gdzie jest sterowiec? Dobrze się składa, mam tu swój lokalizator sterowców!', 0),
(22185, 'koKR', 'Gdzie jest teraz sterowiec do Orgrimmaru?', 'Gdzie jest teraz sterowiec do Orgrimmaru?', 0),
(23264, 'koKR', 'W Zaduszniki świętujemy dzień, w którym sama Królowa Banshee wyrwała nas ze szponów Króla Lisza i Plagi. Koniecznie przyjdź na festiwal Wiklinowego Człowieka, który odbywa się co wieczór pod Podmiastem.', 'W Zaduszniki świętujemy dzień, w którym sama Królowa Banshee wyrwała nas ze szponów Króla Lisza i Plagi. Koniecznie przyjdź na festiwal Wiklinowego Człowieka, który odbywa się co wieczór pod Podmiastem.', 0),
(24654, 'koKR', 'Tam! Tam!', 'Tam! Tam!', 0),
(27028, 'koKR', '', 'Jeszcze się okaże.', 0),
(32691, 'koKR', 'Zbyt długo mnie nie było. Moja nieobecność kosztowała życie kilku naszych największych bohaterów. Śmieciom takim jak ty i ta zła wiedźma pozwolono chodzić wolno – bez żadnej kontroli.', '', 0),
(32693, 'koKR', 'Nadszedł czas, by naprawić krzywdy. By rozwiązać wasze zdradzieckie królestwo morderców i złodziei. Putress był pierwszym ciosem. Będzie ich znacznie więcej.', '', 0),
(32697, 'koKR', 'Długo na to czekałem, Thrallu. Za każdym razem, gdy rzucano mnie na jedną z waszych przeklętych aren... za każdym razem, gdy zabijałem takiego zielonoskórego wybryka natury jak ty... mogłem myśleć tylko o jednym.', '', 0),
(32699, 'koKR', 'O tym, czym mógłby być nasz świat bez ciebie i twojej wypaczonej Hordy... To koniec, wodzu.', '', 0),
(32700, 'koKR', 'DO ATAKU! ZA WICHROGRÓD! ZA BOLVARA! ZA PRZYMIERZE!', '', 0),
(32709, 'koKR', '', 'VARIANIE, NIE! STÓJ!', 0),
(32711, 'koKR', '', 'Nie musiało tak być...', 0),
(32829, 'koKR', 'Bądź $ggotów:gotowa;, $n. Atakujemy, gdy tylko nadciągną wszystkie nasze siły!', '', 0),
(32837, 'koKR', 'Ostatnia bitwa wkrótce się zacznie, $n. Baczność!', '', 0),
(32843, 'koKR', 'Bohaterowie Przymierza, wasz król wzywa! Zbierzcie się za mną przy wejściu do kanałów!', '', 0),
(32844, 'koKR', 'Wkrótce wyruszymy na to przeklęte miejsce i oczyścimy je ze zła!', '', 0),
(32847, 'koKR', 'Godzina odkupienia jest bliska! Przygotujcie się!', '', 0),
(32849, 'koKR', 'Marsz na Podmiasto zaczyna się teraz! Niech siła waszego króla doda wam mocy! Za mną, bohaterowie! KU CHWALE PRZYMIERZA!', '', 0),
(32856, 'koKR', 'Naprzód, bracia i siostry! Przeznaczenie czeka!', '', 0),
(32858, 'koKR', 'Zaczynamy zejście w otchłań zepsucia! Miejcie się na baczności! Jaino, użycz nam swojej siły!', '', 0),
(32865, 'koKR', '', 'Natychmiast, Wasza Wysokość!', 0),
(32937, 'koKR', 'Twoje wynaturzone twory nie mają szans z Przymierzem, Putressie! Idziemy po ciebie!', '', 0),
(32938, 'koKR', 'Żołnierze, w szereg! Pilnujcie korytarzy!', '', 0),
(32939, 'koKR', '', 'Co tu się stało? Wszędzie trupy... ten smród... nie do zniesienia...', 0),
(32940, 'koKR', 'Horda. Sądząc po śladach walki, są tu w sile – gdzieś w pobliżu.', '', 0),
(32941, 'koKR', 'Bądźcie czujni i gotowi. Nie wiadomo, jakie okropieństwa na nas czekają.', '', 0),
(32945, 'koKR', 'Główna komnata jest tędy! Ruszamy!', '', 0),
(32947, 'koKR', 'Nie masz dokąd uciec, potworze!', '', 0),
(32961, 'koKR', 'Sprawiedliwości stało się zadość!', '', 0),
(32962, 'koKR', 'I co teraz powiesz, Putressie?', '', 0),
(32963, 'koKR', 'Rozejrzyjcie się, bracia i siostry. Otwórzcie oczy! Spójrzcie, co zrobili z naszym królestwem!', '', 0),
(32964, 'koKR', 'Jak długo jeszcze pozwolimy tym dzikusom panoszyć się w naszym świecie?', '', 0),
(32965, 'koKR', 'Widziałem świat Hordy. Byłem w ich miastach. W ich umysłach...', '', 0),
(32966, 'koKR', 'Wiem, jakie zło czai się w sercach orków.', '', 0),
(32968, 'koKR', 'THRALL! TUTAJ?', '', 0),
(32969, 'koKR', 'NAPRZÓD! Skończmy z tym!', '', 0),
(32970, 'koKR', 'Wiedzcie, że orkowie mają okrzyk bojowy: LOK\'TAR OGAR! Znaczy „zwycięstwo albo śmierć”. Jakże stosowne...', '', 0),
(32971, 'koKR', 'Do sali tronowej!', '', 0),
(32972, 'koKR', '', 'Varianie, stój! Nie pomogę ci w tym!', 0),
(32979, 'koKR', 'W tym zbezczeszczonym mieście ukrywa się nędznik winny wymordowania naszych braci i sióstr u Bramy Gniewu! Musi stanąć przed sądem!', '', 0),
(33128, 'koKR', 'Całe to święto jest bez sensu. Kolorowe jajka i „afirmacja życia”, phi.', 'Całe to święto jest bez sensu. Kolorowe jajka i „afirmacja życia”, phi.', 0),
(35101, 'koKR', 'Dlaczego obchodzimy Dary Pielgrzymów...? Kto to wie. Chyba z przyzwyczajenia. Ja w każdym razie nie czuję smaku żadnej z tych potraw.$B$BPlacek dyniowy, zjadliwe zarazy... Czy to naprawdę ważne, CO pichcimy?', 'Dlaczego obchodzimy Dary Pielgrzymów...? Kto to wie. Chyba z przyzwyczajenia. Ja w każdym razie nie czuję smaku żadnej z tych potraw.$B$BPlacek dyniowy, zjadliwe zarazy... Czy to naprawdę ważne, CO pichcimy?', 0),
(36090, 'koKR', 'Utrzymać barykady! Nie oddawajcie im ani piędzi!', '', 0),
(36210, 'koKR', 'Znajdziesz ich w Aptekarium. Nazywają się doktor Herbert Halsey i doktor Marsh. Tylko uważaj na plecy.', 'Znajdziesz ich w Aptekarium. Nazywają się doktor Herbert Halsey i doktor Marsh. Tylko uważaj na plecy.', 0),
(36211, 'koKR', 'Szukasz doktora Herberta Halseya. Tylko bez żadnych numerów. Jeszcze jeden taki wybryk z zarazą, a znajdziesz topór w niewygodnym miejscu.', 'Szukasz doktora Herberta Halseya. Tylko bez żadnych numerów. Jeszcze jeden taki wybryk z zarazą, a znajdziesz topór w niewygodnym miejscu.', 0),
(36216, 'koKR', 'Idź do środkowego kręgu; tam urzędują licytatorzy.', 'Idź do środkowego kręgu; tam urzędują licytatorzy.', 0),
(36217, 'koKR', 'Jeśli chcesz skorzystać z tutejszego targu, idź do środkowego kręgu miasta.', 'Jeśli chcesz skorzystać z tutejszego targu, idź do środkowego kręgu miasta.', 0),
