(36229, 'koKR', 'Nietoperzami Podmiasta zajmuje się Michael Garrett. Znajdziesz go w górnym kręgu Dzielnicy Handlowej.', 'Nietoperzami Podmiasta zajmuje się Michael Garrett. Znajdziesz go w górnym kręgu Dzielnicy Handlowej.', 0),
(36230, 'koKR', 'Treser nietoperzy ma swoją grzędę w górnym kręgu Dzielnicy Handlowej. Nie przegapisz – poznasz po zapachu.', 'Treser nietoperzy ma swoją grzędę w górnym kręgu Dzielnicy Handlowej. Nie przegapisz – poznasz po zapachu.', 0),
(36231, 'koKR', 'Mistrzowie bitewni stacjonują w Królewskim Kwartale; znajdziesz ich przy sali tronowej.', 'Mistrzowie bitewni stacjonują w Królewskim Kwartale; znajdziesz ich przy sali tronowej.', 0),
(36233, 'koKR', 'James Van Brunt prowadzi porządną kuźnię w Dzielnicy Wojennej. Jest w wewnętrznym kręgu.', 'James Van Brunt prowadzi porządną kuźnię w Dzielnicy Wojennej. Jest w wewnętrznym kręgu.', 0),
(36234, 'koKR', 'Tutejszy kowal pracuje w Dzielnicy Wojennej, blisko miejsca, gdzie jego broń idzie w ruch. Znajdziesz go w wewnętrznym kręgu.', 'Tutejszy kowal pracuje w Dzielnicy Wojennej, blisko miejsca, gdzie jego broń idzie w ruch. Znajdziesz go w wewnętrznym kręgu.', 0),
