(36239, 'koKR', 'Tutejszy inżynier nazywa się Franklin Lloyd. Majsterkuje w Dzielnicy Łotrów, w zewnętrznym kręgu.', 'Tutejszy inżynier nazywa się Franklin Lloyd. Majsterkuje w Dzielnicy Łotrów, w zewnętrznym kręgu.', 0),
(36240, 'koKR', 'Słuchaj, jeśli chcesz gadać z tymi inżynierami w zewnętrznym kręgu Dzielnicy Łotrów, to twoja skóra.', 'Słuchaj, jeśli chcesz gadać z tymi inżynierami w zewnętrznym kręgu Dzielnicy Łotrów, to twoja skóra.', 0),
